window.QURAN_DATA[3]={name:'Ali-İmran',meaning:'İmran ailəsi',ayahs:[
 {"n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ","tr":"[İlkin layihə] Rəhman və Rəhim olan Allahın adı ilə. Elif‑Ləm‑Mim.","ex":"Tərcümə: \"Rəhman və Rəhim olan Allahın adı ilə\" hissəsi aydın çevrilir; \"الٓمٓ\" (Elif‑Ləm‑Mim) hərfləri ayrı‑ayrı yazılmışdır və mətnin bir elementi kimi saxlanılır. Şərh: Bu qısa giriş ayəsi müqəddimə rolunu oynayır; ayrılmış hərflərin məhz nəyi ifadə etdiyi mətndə açıq göstərilməyib və müxtəlif şimalarla qarşılanır.","rel":"2:1,29:1,30:1"},
 {"n":2,"ar":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ","tr":"[İlkin layihə] Allahdan başqa heç bir ilah yoxdur; O diridir, hər şeyi qaim tutandır.","ex":"Tərcümə: Ayə Allahın təkliyini və iki isimini verir: \"Həyat sahibi\" və \"Qaim/Dayaq olan\". Şərh: Bu ifadələr Quran daxilində Allahın əzəli hakimiyyəti və davamlı nəzarətini vurğulayır; oxşar isimlər başqa yerlərdə də təkrarlanır (məsələn, 2:255).","rel":"2:255"},
 {"n":3,"ar":"نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","tr":"[İlkin layihə] O (Allah) sənə kitabı haqqla nazil etdi; o, əvvəllər mövcud olanların təsdiqidir və Tövratla İncil də nazil etmişdir.","ex":"Tərcümə: Ayə Qurani‑Kərimin Peyğəmbərə haqq olan kitab kimi endiyini və əvvəlki kitabları təsdiq etdiyini ifadə edir. Şərh: Burada Quranın başqa ilahi kitablarla bağlı təsdiqedici mövqeyi bildirilir; bu, nə dərəcədə uyğunluq və ya təfsir məsələlərinin necə başa düşülməsi lazım olduğu barədə dəqiq texniki izah vermir.","rel":"3:3,10:37"},
 {"n":4,"ar":"مِن قَبْلُ هُدًۭى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۭ ۗ وَٱللَّهُ عَزِيزٌۭ ذُو ٱنتِقَامٍ","tr":"[İlkin layihə] O, (əvvəllər) insanların hidayəti üçün (də) göndərdi və Furqanı (haqqla batili ayıranı) nazil etdi. Şübhəsiz ki, Allahın ayələrini inkar edənlərin ağır əzabı var; Allah qüdrətlidir, intiqam sahibidir.","ex":"Tərcümə: Ayə Quranın həm hidayət, həm də \"Furqan\" — doğru ilə yanlışın ayırd edicisi — kimi göndərildiyini deyir və inkarın cəza ilə nəticələnəcəyini xəbər verir. Şərh: \"Furqan\" sözünün məna spektri var (məsələn, fərq edən, hökm verən); cəzanın xarakteri barədə qısa bəyanat var, amma detalları ayədə verilməyib.","rel":"25:1"},
 {"n":5,"ar":"إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌۭ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ","tr":"[İlkin layihə] Həqiqətən, yerdə də, göylərdə də heç nə Allahdan gizli deyil.","ex":"Tərcümə: Ayə Allahın bilik və nəzarətinin bütün məkanları əhatə etdiyini ifadə edir. Şərh: Bu, Allahın hər şeyi görüb bildiyi anlayışını vurğulayır; ayənin konkret nəticələri və insan məsuliyyətinə dair təfsir burada məhduddur.","rel":"6:59"},
 {"n":6,"ar":"هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tr":"[İlkin layihə] O sizin ana bətnlərinizdə sizi necə istəsə elə biçimə salandır. Ondan başqa ilah yoxdur; O qüdrətli və hikmət sahibidir.","ex":"Tərcümə: Ayə Allahın insanı ana bətnində formalaşdıran olduğunu bildirir və Onun əzəmətini, hikmətini qeyd edir. Şərh: Bu ifadə yaradılış prosesinə dair ilahi rolun vurğulanmasıdır; ayə hansı mexanizmlə və nə qədər detalda təsəvvür ediləcəyi barədə konkret teknik məlumat vermir.","rel":"39:6"},
 {"n":7,"ar":"هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌۭ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌۭ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌۭ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّۭ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ","tr":"[İlkin layihə] O sizin üzərinizə kitabı nazil etdi; ondan muhkəm ayələr vardır — onlar kitabın əsasıdır — və başqaları isə oxşar (müəmmalı)dır. Ürəklərində əyrilik olanlar oxşarına (müəmmalıya) uyarlar ki, fitnə axtarsınlar və onun təfsiri üçün; onun təfsirini yalnız Allah bilər. Eləcə də elmə möhkəm tutulanlar deyirlər: “Biz Ona iman gətirdik; hər şey Rəbbimizdən gəlir.” Yalnız ağıl sahibi olanlar tövbə götürər.","ex":"Tərcümə: Ayə Quranın bəzi ayələrinin açıq və möhkəm, bəzi ayələrinin isə oxşar/müəmmal olduğunu bildirir; müxtəlif qrupların bu ayələrə reaksiyası təsvir edilir. Şərh: Burada iki mövqe — ürəkləri sapmışların mübahisə axtarması və elm sahiblərinin təvazökar imanı — qarşılaşdırılır; \"təfsir\" və \"müəmmal\" məsələlərinin tam izahı ayədə təmin olunmur və təfsiri Allahdan başqa kimsənin tam bildiyi vurğulanır.","rel":"2:106,10:94"},
 {"n":8,"ar":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ","tr":"[İlkin layihə] (Onlar dua etdilər:) “Rabbimiz! Hidayət etdikdən sonra qəlblərimizi sapdırma və Özündən bizə rəhmət bağışla; həqiqətən, Sən ən böyük hədiyyə verənəsən.”","ex":"Tərcümə: Bu dua hidayət verildikdən sonra sapma olmaması və Allahdan rəhmət diləməyi ifadə edir; son cümlə Allahın \"Vəhhab\" (mövzuya geniş hədiyyə verən) olduğunu vurğulayır. Şərh: Ayə möminlərin qorxusu və ehtiyacı olan dua modelini verir; \"Vəhhab\" sifəti Allahın səxavətini və lütfünü işarə edir, lakin bu xüsusiyyətin tətbiqinin üsulu ayədə izah edilmir.","rel":"2:286"},
 {"n":9,"ar":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ","tr":"[İlkin layihə] (Onlar dedilər:) “Rabbimiz! Həqiqətən Sən insanları şübhə olmayan bir gündə toplayansan; şübhəsiz ki, Allah və'dini pozmaz.”","ex":"Tərcümə: Ayə Qiyamət günü insanların toplanacağını və Allahın vədinin yerinə yetirəcəyini ifadə edir. Şərh: Burada dirilib toplanma və Allahın andının təminatı vurğulanır; bu hadisənin necə baş verəcəyi barədə ayədə texniki detallar verilmir.","rel":"22:7"},
 {"n":10,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ","tr":"[İlkin layihə] Həqiqətən, kafir olanların malları və övladları onlara Allah qarşısında heç bir fayda verməz; onlar Odun üçün yanacaqdırlar.","ex":"Tərcümə: Ayə dünyəvi sərvətlərin və nəslin inkar edənləri Allahın əzabından qurtarmayacağını bildirir və onları \"odun yanacağı\" kimi təsvir edir. Şərh: Bu metaforik ifadə cəzaya dair xəbərdarlıqdır; ayə konkret fəlsəfi və ya hüquqi nəticələr təqdim etmir, yalnız Quran kontekstində xəbərdarlıq və nəticə nümunəsi verir.","rel":"8:36"},
 {"n":11,"ar":"كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ","tr":"Bu, Firon ailəsinin və onlardan əvvəlkilərin halına oxşayırdı. Onlar ayətlərimizi inkar etdilər; buna görə də Allah onları günahlarına görə ələ keçirdi. Allah əzabı möhkəm verəndir.","ex":"Tərcümə ayənin ümumi mənasını verir: keçmiş ümmətlərin ayətləri rədd etdikləri üçün cəzalandırıldığını bildirir. Şərh olaraq: mətn konkret bir hadisəni nümunə kimi göstərir və burada “ələ keçirmək” ifadəsi Allahın günahlarına görə tədbir görməsini ifadə edir; hansı xüsusi nəticələrin nəzərdə tutulduğu ayədə dəqiq göstərilməyib.","rel":"7:103-137,10:83-92"},
 {"n":12,"ar":"قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ","tr":"De: “İman gətirməyənlər, siz məğlub olub cəmlənərək Cəhənnəmə toplanacaqsınız. Və nə pis məskəndir!”","ex":"Tərcümə ayənin xəbər və xəbərdarlığını saxlayır: kəfir olanların məğlub olub mərhəmətsiz bir yerə toplanacaqları bildirilir. Şərh olaraq: burada “məğlub olmaq” və “cəmlənmək” ifadələri axirətdə yenilginin və cəzanın ümumi təsviridir; mətn şəxslərin taleyinin Allahın hökmünə tabe olduğunu vurğulayır.","rel":"6:128,2:257"},
 {"n":13,"ar":"قَدْ كَانَ لَكُمْ ءَايَةٌۭ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌۭ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌۭ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّأُو۟لِى ٱلْأَبْصَٰرِ","tr":"Sizin üçün bir nümunə vardır: iki dəstə qarşılaşdı. Bir dəstə Allah yolunda döyüşür, digəri isə kafir idi; onlar özlərini onların qarşısında ikiqat sayırmış kimi gördülər. Allah Öz yardımı ilə istədiyini dəstək verir. Şübhəsiz ki, bunda görənlərin üçün ibrət vardır.","ex":"Tərcümə qarşılaşan iki qrupun təsvirini verir və Allahın yardımının qətiliyini bildirir. Şərh olaraq: ayə döyüş səhnəsi kimi oxunsa da, əsas vurğu Allahın yardımını və insanların müşahidə edə biləcəyi ibrət dərsini göstərməkdir; “onlar özlərini ikiqat görürdülər” ifadəsi müharibədə rəqəmlərin gözlə görünən kimi alınmamasına işarə edə bilər, lakin mətn öz-özünə detallar vermir.","rel":"8:17,8:65"},
 {"n":14,"ar":"زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ","tr":"İnsanlara qadınların, oğulların, çoxlu xazinaların — qızıl və gümüşün —, damğalı atların, mal-qara və məhsulun həvəslə sevilməsi gözəl göstərildi. Bunlar dünya həyatının nemətləridir; Allah yanında isə yaxşı dönüş (əcr) vardır.","ex":"Tərcümə dünya həyatının cazibədar nemətlərinin siyahısını və onların faniliyini bildirir. Şərh olaraq: ayə dünya bərəkətlərinin insana cazibədar görünməsini qeyd edir və onları müvəqqəti olaraq səciyyələndirir; “Allah yanında yaxşı dönüş” ifadəsi axirətdən gələn daha yüksək mükafatı vurğulayır.","rel":"18:46,57:20"},
 {"n":15,"ar":"۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍۢ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌۭ مُّطَهَّرَةٌۭ وَرِضْوَٰنٌۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ","tr":"De: “Sizə bundan daha xeyirli olanı xəbər verimmi? (Allahdan) qorxanlar üçün Rəbblərinin yanında altında çaylar axan cənnətlər vardır; orada əbədi qalacaqlar, təmizlənmiş həyat yoldaşları və Allahdan razılıq vardır. Allah qullarına nə etdiklərini görəndir.”","ex":"Tərcümə dünya nemətlərindən daha üstün olan axirət mükafatını təsvir edir. Şərh olaraq: ayə iman gətirənlərin qorxub-taqvalı olduqları halda Allahın yanında əbədi mükafatların olduğunu bildirir; burada “təhlükəsiz” vəd vəd olunur, lakin konkret təsvirlər metaforik ola bilər.","rel":"2:25,4:57"},
 {"n":16,"ar":"ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","tr":"Onlar dua edirlər: “Ey Rəbbimiz! Həqiqətən biz iman gətirdik, bizi günahlarımızdan bağışla və bizi Cəhənnəm əzabından qoru.”","ex":"Tərcümə bu dua-cəza istəksizliyini və tövbə niyyətini çatdırır. Şərh olaraq: ayə iman gətirənlərin əsas tövbə və əfv istəklərini göstərir; mətn ümumi bir ibadət diləyi verdiyni bildirir, xüsusi mərhələlər və ya ayinlər göstərmir.","rel":"2:286,40:7"},
 {"n":17,"ar":"ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ","tr":"Səbirli olanlar, doğru danışanlar, səcdə edənlər, xərcləyənlər və saharlarda (səhər erkən) bağışlanma diləyənlərdir.","ex":"Tərcümə burada qeyd olunan davranış və əxlaq xassələrini sadalayır. Şərh olaraq: ayə bir neçə xasiyyəti qısaca müəyyən edir; hansı səviyyədə və necə tətbiq ediləcəyi mətn daxilində konkretləşdirilməyib, buna görə də fərqli oxunuşlarda vurğu dəyişə bilər.","rel":"2:177,33:33"},
 {"n":18,"ar":"شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tr":"Allah şahiddir ki, Ondan başqa heç bir tanrı yoxdur, mələklər və elm sahibləri də ədalətlə ayaqda duraraq (bunu) təsdiq edirlər. Ondan başqa heç bir tanrı yoxdur; O, Qüdrətli, Həkimdir.","ex":"Tərcümə ayənin Allahın yeganəliyini Allah, mələklər və bilikli şəxslərin ədalətli şəkildə təsdiq etdiyini bildirir. Şərh olaraq: “ayaqda duraraq ədalətlə” ifadəsi təsdiqin ciddi və məsuliyyətli olduğunu vurğulayır; bu şahidlik ifadəsinin konkret məzmunu və hansı şəxslərin nəzərdə tutulduğu mətnin özündən açıq şəkildə çıxmır.","rel":"2:163,6:18"},
 {"n":19,"ar":"إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ","tr":"Həqiqətən, din Allah yanında İslamdır. Kitab verilənlər arasında ixtilaf, onlara elm gələndən sonra yalnız öz aralarındakı qarşıdurma və düşmənçilik üzündən oldu. Kim Allahın ayələrini inkar edərsə, Allah sürətli hesab edən kimsədir.","ex":"Tərcümə əsas bəyanı verir: Allah yanında dinin təslimiyyət (İslam) olduğunu və Kitab verilənlərin elm gəldikdən sonra bir-biri ilə ixtilaf etdiklərini bildirir. Şərh olaraq: ayə həm teolojik iddia (dinə təslim olmaq), həm də tarixi müşahidə (elm gəldikdən sonra ixtilaf) bildirir; “Allah sürətli hesab edən” ifadəsi axirətdə hesabın sürətli olacağı xəbərdarlığı kimi başa düşülə bilər.","rel":"3:85,5:48"},
 {"n":20,"ar":"فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّۦنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ","tr":"Əgər sənə mübahisə etsələr, de: “Mən üzümü (yəqin) Allahın xatirinə təslim etmişəm, və mənim ardımdan gələnlər də.” De ki, Kitab verilənlər və cahillərə: “Siz də təslim oldunuzmu?” Əgər təslim olsalar, onlar doğru yola gəlmişlər; əgər üz döndərsələr, sənin üzərinə ancaq (vəzifə) xəbər vermək düşür. Allah qullarına tam görəndir.","ex":"Tərcümə mübahisə zamanı peyğəmbərin cavabını və insanlara çağırışı əks etdirir: özünü Allah qarşısında təslim etdiyini bəyan edir və başqalarına da soruşur. Şərh olaraq: ayə peyğəmbərin məsuliyyətini “təbliğ etmək”lə məhdudlaşdırır; nəticə insanların seçimindən asılıdır və mətn sonda Allahın hər şeyi bildiyini vurğulayır.","rel":"2:208,4:65"},
 {"n":21,"ar":"إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ حَقٍّۢ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","tr":"(ilk layihə) Həqiqətən Allahın ayələrinə inanmayanlar, peyğəmbərləri haqsız yerə öldürənlər və insanlara ədaləti əmr edənləri öldürənlərə ağrılı bir əzabın müjdəçisi ol.","ex":"Tərcümə: Ayə inanmayanları və haqsız qətlləri xəbər verir və onlar üçün əzab vəd edir. Şərh: Burada diqqət həm Allahın ayələrinə inanmamağa, həm də peyğəmbərlərə və ədalət müjdəçilərinə qarşı edilən zorakılığa yönəlib; mətn konkret şəxsləri cəza ilə hədələyir, buna dair necə həyata keçiriləcəyi barədə detallar vermir.","rel":""},
 {"n":22,"ar":"أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ","tr":"(ilk layihə) Onlar ki, əməlləri həm dünyada, həm də axirətdə batil olmuşdur; və onların heç bir köməkçisi yoxdur.","ex":"Tərcümə: Bu ayə həmin cinayətkarların əməllərinin müvəffəqiyyətsiz olduğunu və onların yardımçısız qalacağını deyir. Şərh: “Əməllərin batil olması” həm xeyirli nəticələrin itməsi, həm də mükafatdan məhrum olma mənasında anlaşılır; burada mühakimə məqamı qəti və ümumidir.","rel":""},
 {"n":23,"ar":"أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُمْ وَهُم مُّعْرِضُونَ","tr":"(ilk layihə) Gördünmü sənə Kitabdan bir pay verilmiş olanları? Onlar Allahın Kitabına (hüquq və qərar üçün) dəvət olunurlar, sonra onların bir qrupu ondan üz döndərir və onlar nankor və dönməzdirlər.","ex":"Tərcümə: Ayə Kitab verilənlərin Allahın Kitabına söykənib hökm üçün çağırılmasını və sonra bir qrupun ondan üz çevirməsini vurğulayır. Şərh: Burada tənqid məhz çağırışa cavab verməyən və hökmün tətbiqindən çəkilən qruplara yönəlir; kimlərin nəzərdə tutulduğu və onların səbəbləri ayədən kənar əlavə izah tələb edir.","rel":""},
 {"n":24,"ar":"ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًۭا مَّعْدُودَٰتٍۢ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ","tr":"(ilk layihə) Bu, ona görədir ki, onlar dedilər: “Od yalnız bizim üçün sayılıb-seçilmiş bir neçə günə toxunar.” Və dinlərində ixtira etdikləri şey onları aldatdı.","ex":"Tərcümə: Ayə onların “od yalnız qısa müddət toxunacaq” deyərək özlərini aldadıqlarını göstərir. Şərh: Burada qeyd olunan ismi-ixtira və aldanma, onların ölüm və cəza haqda yüngülləşdirici düşüncələri ilə bağlıdır; ayə bu düşüncənin təhlükəsinə diqqət çəkir, lakin ətraflı psixoloji səbəblər göstərmir.","rel":""},
 {"n":25,"ar":"فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ","tr":"(ilk layihə) Bəs necə olar ki, Biz onları şübhəsi olmayan bir gün üçün toplayacağı zaman — hər nəfərə etdiyi əməyin haqqı tam veriləcək və onlara zülm olunmayacaq.","ex":"Tərcümə: Ayə Qiyamət günündə hər kəsin əməyinin hesabının veriləcəyini və zülm edilməyəcəyini bildirir. Şərh: “Şübhəsi olmayan gün” ifadəsi axirətdəki hesabın qəti və ədalətli olacağına işarə edir; burada mətn ədalətin dəqiq olacağını qeyd etsə də, cəza və mükafatın necə olacağı barədə təfsirə açıqdır.","rel":""},
 {"n":26,"ar":"قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","tr":"(ilk layihə) De: “Allahım, Sən hakimiyyətin sahibisən. Sən hakimiyyəti istədiyinə verərsən, istədiyindən alarsan; istədiyini əziz edərsən, istədiyini təqəzzaya salarısan. Xeyir sənin əlindədir. Həqiqətən Sən hər şeyə qadirsən.”","ex":"Tərcümə: Mövzu Allahın hökmranlığı, vermə və alma, ucaldıb alçaltması üzərində qurulub. Şərh: Bu sözlər Allaha tabeçilik və O'nun iradəsinə təslimiyyət ifadəsidir; ifadələr Uca Rəbbin gücünü və idarəetməsini vurğulayır, mənaları isə geniş və metafizikdir.","rel":""},
 {"n":27,"ar":"تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍۢ","tr":"(ilk layihə) Sənə gecəni gündüzə, gündüzü isə gecəyə daxil edirsən; canlıyı ölüyədən, ölüyu canlıdan çıxarırsan; və hesabsız olaraq istədiyinə ruzı verirsən.","ex":"Tərcümə: Ayə Allahın təbiətdə və həyat-ölümdəki çevirməedici qüdrətini sadalayır. Şərh: Bu cümlələr təbiət hadisələrinin və rizq verilməsinin Allahın nəzarətində olduğunu göstərir; “hesabsız olaraq” ifadəsi Allahın səxavətinin ölçüsüz olduğunu bildirir, amma konkret mexanizmlər açıqlanmır.","rel":""},
 {"n":28,"ar":"لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةًۭ ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ","tr":"(ilk layihə) Mənəmlərin (möminlərin) kafirləri möminlərdən başqa əwliyə götürmələri olmaz; kim bunu edərsə, o artıq Allahdan heç bir şey deyil — istisna olaraq əgər onlardan qorxub müvəqqəti ehtiyat tədbiri görürsə. Allah sizi Özündən xəbərdar edir. Və dönüş (son nəticə) Allaha məxsusdur.","ex":"Tərcümə: Ayə möminlərin kimsəni dost və himayəçi seçmə məsələsində xəbərdarlıq edir və bir istisna qeyd edir. Şərh: “İstisna” (təqiyə, qorxudan yaranan müvəqqəti münasibət) məna baxımından mübahisəli və müxtəlif şəkildə təfsir oluna bilər; ayə ümumilikdə icma loyallığı və təhlükəyə qarşı ehtiyatı nəzərə alır.","rel":""},
 {"n":29,"ar":"قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","tr":"(ilk layihə) De: “Gizlətdiyiniz nədirsə, qəlblərinizdə olanı və ya onu açıq bildirsəniz də, Allah onu bilir. O, göylərdə və yerdə olanları da bilər. Allah hər şeyə qadirdir.”","ex":"Tərcümə: Bu ayə insanın daxili düşüncələri və niyyətlərinin Allah tərəfindən bilinməsini vurğulayır. Şərh: Mətn həm gizli, həm açıq əməllərin hamısının Allahın elmi altına düşdüyünü xatırladır; bunun nəticəsi olaraq hesabatın tam və ədalətli olacağı bildirilir.","rel":""},
 {"n":30,"ar":"يَوْمَ تَجِدُ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ مِنْ خَيْرٍۢ مُّحْضَرًۭا وَمَا عَمِلَتْ مِن سُوٓءٍۢ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًۭا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ","tr":"(ilk layihə) O gün hər nəfər gördüyü yaxşı əməlləri hazır (görünən) halda və etdiyi pislikləri də görəcək; o aralarında böyük bir məsafə olmasını arzulayacaq. Allah Özündən xəbərdar edir sizi; Allah isə bəndələrə qarşı rəhmli və mehribandır.","ex":"Tərcümə: Ayə Qiyamət günündə insanların etdikləri yaxşı və pis işləri görəcəklərini və pis əməllərin gətirdiyi peşmanlığı təsvir edir. Şərh: “Böyük məsafə” ifadəsi peşmanlığın dərinliyini və geri dönüşün mümkün olmamasını bildirir; eyni zamanda Allahın insanlara rəhmli olduğu vurğulanır, bu isə həm ədalət, həm də mərhəmət mövzusunu bir arada saxlayır.","rel":""},
 {"n":31,"ar":"قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ","tr":"De: “Əgər siz Allahı sevirsinizsə, məni izlə(yin); Allah da sizi sevər və günahlarınızı bağışlayar. Allah çox bağışlayandır, rəhmli olandır.”","ex":"Tərcümə: Peyğəmbərə itaət etmək Allahın sevgisinə nail olmaq yolu kimi göstərilir və bunun nəticəsi olaraq günahların bağışlanması vəd edilir. Şərh: “Məni izlə(yin)” ifadəsi burada peyğəmbərin gətirdiyi vəhyə və çağırışa tabe olmağı işarə edir; bu iddianın şərtləri və tətbiqi kontekstdən asılıdır və ayə özü bu şərtləri ayrıca açıqlamır.","rel":"3:32"},
 {"n":32,"ar":"قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ","tr":"De: “Allahın və Rəssulun (elçinin) əmrinə itaət edin. Əgər (onlar) üz çevirsələr, bilin ki, Allah kəfərləri sevməz.”","ex":"Tərcümə: İnsanlara Allah və elçinin göstərişlərinə əməl etmələri tövsiyə edilir; qarşılıq verməmək, dönmək qınanır. Şərh: “Kəfir” sözü ayədə Allah və Rəsulun çağırışından üz döndərənləri təsvir edir; ayə itaət və imtina arasında seçimi vurğulayır.","rel":"3:31"},
 {"n":33,"ar":"۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًۭا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ","tr":"Həqiqətən, Allah Adəmi, Nuhi, İbrahimin ailəsini və İmranın ailəsini aləmlərə üstün etmişdir.","ex":"Tərcümə: Allahın müəyyən şəxsləri və nəsilləri seçdiyini bildirir. Şərh: Ayə onların Allah tərəfindən seçildiyini bildirir, lakin seçimin nə ilə bağlı olduğu və məqamların təfsiri ayədə izah olunmur; bu, yalnız onların xüsusi mövqe və nümunə kimi nəzərə alındığını göstərir.","rel":"3:34-37"},
 {"n":34,"ar":"ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍۢ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tr":"Onların nəsilləri bir-birindən olur. Allah eşidən, biləndir.","ex":"Tərcümə: Burada ailə nəsillərinin bir-birindən gəldiyi qeyd edilir və Allahın eşidən və bilən olduğu xatırladılır. Şərh: “Nəsillərdən biri digərindən” ifadəsi nəsil əlaqəsini göstərir; son cümlə isə Allahın hər şeyi bilib eşitdiyini vurğulayır və əvvəlki seçimi izləyən ümumi anlayışı tamamlayır.","rel":"3:33"},
 {"n":35,"ar":"إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًۭا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ","tr":"(Xatırlayın) İmranın arvadı demişdi: “Rəbbim! Mən qarınımdakı nə varsa Sənin üçün həsr etdim; onu qəbul et məndən; həqiqətən, Sən eşidən və biləndirsən.”","ex":"Tərcümə: İmranın arvadı qarındakı çörəyi və ya övladı Allaha həsr etdiyini bildirir və onun qəbul edilməsini diləyir. Şərh: “Muharraran” sözü burada həsr etmək/məxsus etmək mənasında işlənir; dəqiq məna (məsələn, ritualla həsr etmək, ibadət üçün ayırmaq və s.) ayədə açıq-aydın verilmir, yalnız adanma niyyəti bildirilir.","rel":"3:36-37"},
 {"n":36,"ar":"فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ","tr":"Amma o doğanda dedi: “Rəbbim, mən qız doğdum; Allah daha yaxşı bilir nə doğdu. Kişi qadın kimi deyil. Mən ona Məryəm adını qoydum və onu və nəslini lənətlənmiş şeytandan Sənin hüzurunda sığınma ilə qoruyuram.”","ex":"Tərcümə: Doğuşdan sonra o, qız doğduğunu və ad qoyduğunu, həmçinin onu və nəsilini şeytandan qorumalı olduğunu bildirir. Şərh: Ayə doğulanın cinsinə işarə edir və ananın niyyəti—Məryəmə ad qoyması və onun üçün Allahdan qorunma diləməsi—aydın şəkildə verilir; niyyətin konkret səbəbləri ayənin özündə detallandırılmır.","rel":"3:35-37"},
 {"n":37,"ar":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍۢ وَأَنۢبَتَهَا نَبَاتًا حَسَنًۭا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًۭا ۖ قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ","tr":"Rəbb onun adını xeyirli qəbul etdi, onu gözəl bir şəkildə yetişdirdi və ona Zəkəriyyanı qəyyim etdi. Hər dəfə Zəkəriyyə məhrapa daxil olanda onun yanında ruzisi tapardı. O dedi: “Ey Məryəm, bu necə sənə gəlir?” O dedi: “O, Allahdandır. Həqiqətən, Allah istədiyini hesabsızca ruzi edər.”","ex":"Tərcümə: Allah Məryəmi müsbət bir qəbul ilə qəbul etdi, onu yaxşı şəkildə yetərd və Zəkəriyyəni onun himayəsinə verdi; Zəkəriyyə onun yanında ruzinin mövcud olduğunu gördü və Məryəm bunu Allahdan bildirdi. Şərh: “Qəbulu həssan” və “nabatən həssan” ifadələri Allaha həsr edilmiş bir qəbul və yetişməyi ifadə edir; Məryəmin ruzini Allahdan bilməsi və bunun hesabsız ruzi olduğunu deməsi ayənin bildirdiyi əsas məqamdır.","rel":"3:35-39"},
 {"n":38,"ar":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةًۭ طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","tr":"Orada Zəkəriyyə Rəbbinə dua etdi: “Rəbbim! Öz yanında mənə saleh bir nəsil bəxş et. Həqiqətən, Sən duaları eşidənsən.”","ex":"Tərcümə: Zəkəriyyə Allaha saleh övlad diləyir və Allahın duaları eşidən olduğunu etiraf edir. Şərh: Ayə dua və Allahın eşitməsi arasındakı əlaqəni göstərir; Zəkəriyyənin xahişi onun nəsil və davamlıq istəyini ifadə edir.","rel":"3:37-39"},
 {"n":39,"ar":"فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌۭ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍۢ مِّنَ ٱللَّهِ وَسَيِّدًۭا وَحَصُورًۭا وَنَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ","tr":"O zaman (o məqamda) mələklər ona - o məhrapda ibadət edərkən - dedilər: “Allah səni Yehya ilə müjdələyir; o, Allahın kəlamını təsdiq edən, üstdə yer alan, iffetli və salehlərdən bir peyğəmbər olacaq.”","ex":"Tərcümə: Mələklər Zəkəriyyəni Yehya adlı bir övladla müjdələyirlər və onun xassələrini qısa şəkildə sadalayırlar. Şərh: Ayədə verilən sifətlər (kəlmə ilindən təsdiq etmə, sayılan sifətlər və peyğəmbərliyi) məhz həmin şəxsin ümumi xarakteri və rolu barədə məlumat verir; bu sifətlərin spesifik mənaları mətn daxilində ümumi şəkildə təqdim olunur.","rel":"3:38-40"},
 {"n":40,"ar":"قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌۭ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ","tr":"O dedi: “Rəbbim, mənə necə oğul olacaq? Mən qocalmışam və həyat yoldaşım sonsuzdur (uşaq gətirmir).” Rəbb dedi: “Belədir; Allah istədiyini edər.”","ex":"Tərcümə: Zəkəriyyə yaşlılığını və arvadının suburəyini (uşaq verməməsini) qeyd edərək sual verir; cavab olaraq Allahın iradəsinin hər şeyi həyata keçirdiyi bildirilir. Şərh: Ayə insanın məhdudlığı ilə Allahın qüdrəti arasındakı fərqi vurğulayır; burada Allahın “istəyini yerinə yetirməsi” ifadəsi hadisələrin İlahi iradə ilə mümkün ola biləcəyini göstərir, detal isə ayədə ayrıca şərh olunmur.","rel":"3:38-39"},
 {"n":41,"ar":"قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةًۭ ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًۭا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًۭا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ","tr":"(Zəkəriyyə) dedi: “Rabbim, mənə bir mö’cüzə ver.” Rəbb dedi: “Sənin mö’cüzən budur ki, üç gün insanlarla danışmayacaqsan, yalnız işarə ilə. Rəbbini çox zikr et və axşam və səhərin erkən vaxtlarında O’nu təqdis et.”","ex":"Tərcümə: bu ayə Zəkəriyyənin Allahdan işarə istəməsini və ona verilən işarəni bildirir. İzahedici qeyd: “işarə” olaraq göstərilən üç günlük susqunluq konkret bir möcüzə kimi təqdim olunur; “əş-şə” (axşam) və “əl-əbkār” (səhərin erkən vaxtları) ifadələrinin dəqiq vaxt dairəsi Quranda sintaktik olaraq məhdudlaşdırılmamışdır.","rel":"19:2-15"},
 {"n":42,"ar":"وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ","tr":"Və mələklər dedilər: “Ey Məryəm, həqiqətən Allah səni seçdi, səni pak etdi və səni aləmlərin qadınları arasında seçdi.”","ex":"Tərcümə: mələklərin Məryəmə ünvanladığı mədh və seçilmə sözləri təqdim olunur. İzahedici qeyd: “seçdi” və “pak etdi” sözləri Məryəmin Qurandakı xüsusi mövqeyini ifadə edir; bunun məna və əhatəsi yalnız Qurandakı bu bəyanatla məhdudlaşdırılmalıdır.","rel":"3:42"},
 {"n":43,"ar":"يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ","tr":"“Ey Məryəm, Rəbbinə itaət et, səcdə et və rükû edənlərlə birlikdə rükû et.”","ex":"Tərcümə: Məryəmə itaət, səcdə və ibadətdə iştirak tövsiyə edilir. İzahedici qeyd: “iqnuti” sözü təvazu və Allaha yönəlmə mə’nasını daşıyır; burada ümumi ibadət davranışına çağırış görünür.","rel":"3:43"},
 {"n":44,"ar":"ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ","tr":"Bu, ghayb xəbərlərindən biridir ki, Biz onu sənə vəhy edirik. Və sən onların arasında olanda onların hansısa biri Məryəmi məsuliyyətinə götürsün deyə qələm atdıqları vaxt yanında deyildin, nə də onlar mübahisə etdikləri vaxt yanında idin.","ex":"Tərcümə: Allah peyğəmbərə vəhy vasitəsilə görünməyən məlumatlar verdiyini bildirir və o dövrlərdə onun fiziki iştirakının olmadığını qeyd edir. İzahedici qeyd: burada ifadə olunan “xəbər” Qurana verilən vəhy kimi təqdim olunur və nəqli hadisələrin peyğəmbərin şəxsən şahidi olmadığı vurğulanır.","rel":"19:16-21"},
 {"n":45,"ar":"إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍۢ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ","tr":"Mələklər dedilər: “Ey Məryəm, həqiqətən Allah sənə Özündən bir sözlə müjdə verir; onun adı Məsih İsa, Məryəmin oğlu olacaq, dünyada da axirətdə də şanlıdır və Allaha yaxın olanlardan olacaq.”","ex":"Tərcümə: mələklər İsanın doğulacağı və adının, statusunun nə olacağı barədə xəbər verirlər. İzahedici qeyd: “kəlimə” (Allahdan bir söz) ifadəsi onun yaradılışındakı xüsusi rolun işarəsi kimi verilir; bunun nə dərəcədə metaforik və ya literal anlaşılacağı mətn daxilində fərqli ola bilər.","rel":"3:45"},
 {"n":46,"ar":"وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًۭا وَمِنَ ٱلصَّٰلِحِينَ","tr":"O (İsa) insanlarla beşikdə danışacaq, yetkinlikdə də (danışacaq) və salehlərdən olacaq.","ex":"Tərcümə: ayə İsanın uşaq ikən danışması, yetkinlikdə danışması və saleh olacağı barədə xəbər verir. İzahedici qeyd: “beşikdə danışmaq” Quranın təqdim etdiyi möcüzə nişanlarından biri kimi verilir; bu ifadənin konkret xarakteri mətnin özündən götürülməlidir.","rel":"5:110,3:46"},
 {"n":47,"ar":"قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","tr":"Məryəm dedi: “Rabbim, mənim necə oğlum ola bilər, məni heç bir insan toxunmayıb?” Rəbb dedi: “Belədir. Allah istədiyini yaradır; bir işə hökm verəndə yalnız ona deyir: ‘Ol!’ — və o olar.”","ex":"Tərcümə: Məryəmin heyrətini və Allahın yaradıcılıq üslubunu bildirən cavab təqdim olunur. İzahedici qeyd: “kun fayakun” (“ol” de, olar) ifadəsi burada ilahi yaratma əmrinin sadəliyini vurğulayır və Quranda bir neçə yerdə oxşar məna ilə istifadə olunur.","rel":"3:47,36:82"},
 {"n":48,"ar":"وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ","tr":"Və O ona (İsaya) Kitabı, hikməti, Tövratı və İncilı öyrədəcəkdir.","ex":"Tərcümə: burada İsanın Allaha aid edilən biliklərlə təmin ediləcəyi bildirilir. İzahedici qeyd: “əl-kitāb” ümumi bir termin kimi işlədilir; hansı mətn və ya məzmunu nəzərdə tutduğu bəyanatda məhdudlaşdırılmışdır və Qurandakı digər ayələr kontekstində qiymətləndirilməlidir.","rel":"3:48,5:46"},
 {"n":49,"ar":"وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ","tr":"Və Mən İsrail oğullarına elçiəm: “Mən Sizin Rəbbinizdən bir nişanla gəlmişəm. Sizə gil üzərində quş şəklini yaradar, ona nəfəs üfürərəm, o isə Allahın izni ilə quşa çevrilərəm. Mən koru və lepranı sağlam edərəm, Allahın izni ilə ölüləri dirildirəm. Mən sizə nə yediyinizi və evlərinizdə nə saxladığınızı xəbər verərəm. Bunda sizin üçün əgər mömin olsanız, bir nişan vardır.”","ex":"Tərcümə: İsa peyğəmbərin İsrail oğullarına gətirəcəyi möcüzələr və onların Allahın izni ilə mümkün olduğu bildirilir. İzahedici qeyd: siyahıdakı hadisələr Allahın icazəsi ilə baş verən nişanlar kimi təqdim olunur; “sizin üçün nişan” deməsi onların iman üçün sübut olduğu anlamını daşıyır, lakin ətraflı izah mətn daxilində açıqdır.","rel":"3:49,5:110"},
 {"n":50,"ar":"وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ","tr":"Və Mən öncəki Tövrətə dair olanları təsdiqləyən və sizin üçün haram olan şeylərdən bəzilərini sizə halal edənəm. Mən sizin Rəbbinizdən bir nişanla gəldim; ona görə Allahdan qorxun və mənə itaət edin.”","ex":"Tərcümə: bu ayə İsanın əvvəlki kitabları təsdiqləyəcəyini və bəzi hallarda əvvəlki qadağalardan müəyyən asılılıqlarda icazə verəcəyini bildirir. İzahedici qeyd: “haram olanlardan bəzilərini halal etmək” ifadəsinin konkret şərtləri və tətbiqi Quranda başqa ayələrlə müqayisədə aydınlaşdırılmalıdır; çağırış isə takva (Allah qorxusu) və itaətə yönəlikdir.","rel":"3:50,5:46"},
 {"n":51,"ar":"إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","tr":"İlk layihə tərcümə: Həqiqətən, Allah mənim də, sizin də Rəbbinizdir; Ona ibadət edin. Bu düz yoldur.","ex":"Tərcümə: Ayə Allahın həm danışanın, həm də dinləyənlərin Rəbbi olduğunu bəyan edir və Ona ibadəti əmr edir. Şərh: Kontekstə görə burada danışanın rəyləri və ibadətə çağırışı vurğulanır; “düz yol” ibadət və davranışın doğru formada olmasına işarə edir, lakin mətnin tam mənası kontekstdən asılı olaraq fərqli cəhətlər daşıya bilər.","rel":"Əl-i İmran 3:52-60"},
 {"n":52,"ar":"۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ","tr":"İlk layihə tərcümə: Sonra İsa onlarda küfrü hiss edəndə dedi: “Kim mənim üçün Allaha yardımçı olacaq?” Həvarilər dedilər: “Biz Allahın yardımçılarıyıq; Allaha iman gətirdik və şahidlik et ki, biz təslim olmuşuq (müsəlmanız).”","ex":"Tərcümə: Ayə İsanın tərəfdarlarına yardımçı çağırışı və onların iman bəyanını verir. Şərh: “Həvarilər” burada İsanın yaxın izləyiciləridir və onların sözləri iman və təslimiyyət ifadəsidir; mətn onların mövqeyini qeyd edir, daha geniş tarixçəni və ya əlavə məna çıxarmaları Qurandan kənar mənbələr tələb edər.","rel":"Əl-i İmran 3:51,53"},
 {"n":53,"ar":"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ","tr":"İlk layihə tərcümə: “Ey Rəbbimiz! Sən nazil etdiyinə iman gətirdik və Rəsula itaət etdik; bizi şahidlər arasında yaz.”","ex":"Tərcümə: Həvarilərin dua və xahişidir ki, onların imanları və itaətləri şahidlər sırasında qeyd edilsin. Şərh: “Şahidlər” ifadəsi burada haqqı tanıyan və onun şahidi olanları göstərir; bu, onların Allah qarşısında tanınma arzusunu ifadə edir, konkret hüquqi mənası mətn daxilində açıqlanmayıb.","rel":"Əl-i İmran 3:52-54"},
 {"n":54,"ar":"وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ","tr":"İlk layihə tərcümə: Onlar hiylə qurdular, Allah da hiylə qurdu; Allah hiylə qurucuların ən yaxşısıdır.","ex":"Tərcümə: Ayə qarşı tərəfin plan qurduğunu və Allahın da plan qurduğunu bildirir, Allahın ən yaxşı planlayıcı olduğunu bəyan edir. Şərh: Burada “məkər” sözü plan/tilmə işləmməyi nəzərdə tutur; ayə insan planlarının Allahın hökmü qarşısında necə nəticələnə biləcəyini vurğulayır, lakin konkret hadisənin necə baş verdiyi mətn daxilində tam açıqlanmır.","rel":"Əl-i İmran 3:55"},
 {"n":55,"ar":"إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ","tr":"İlk layihə tərcümə: (O zaman) Allah buyurdu: “Ey İsa, Mən səni (özümə) alacağam, səni Özümə yüksəldəcəyəm, səni inkara düşənlərdən pak edəcəyəm və səni izləyənləri inkara düşənlərin üzərində edəcəyəm qiyamət gününə qədər; sonra hamınız Mənə dönəcəksiniz və Mən sizin aranızda ixtilaf etdiyiniz işlər barəsində hökm edəcəyəm.”","ex":"Tərcümə: Ayə İsanın alınması/şaqqıdılması, ucaldılması və onun və tərəfdarlarının vəziyyətinə dair Allahın sözünü çatdırır. Şərh: “Mutawaffīka” və “rafiʿuka” kimi ifadələr müxtəlif məna çalarlarına malikdir (məsələn, alma, ruhu götürmə, ya da ucalma); burada mətn onları Allaha qaytarmaq və son hökm üçün geri qaytarmaq kimi təqdim edir, lakin təfsir aspektində fərqli oxunuşlar mövcuddur.","rel":"Əl-i İmran 3:56-60"},
 {"n":56,"ar":"فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًۭا شَدِيدًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ","tr":"İlk layihə tərcümə: İnkar edənləri isə Mən dünyada da axirətdə də ağır əzabla cəzalandıracağam; onların heç bir köməkçisi olmayacaq.","ex":"Tərcümə: Ayə inkara düşənlər üçün Allahın cəzasını xəbər verir və onların köməkçisiz qalacağını bildirir. Şərh: Bu, mətnin hədəsi şəklindədir; konkret cəza və mərhələləri barədə əlavə izahata ehtiyac varsa, onu yalnız Qurandakı digər ayələr çərçivəsində qiymətləndirmək olar.","rel":"Əl-i İmran 3:55,57"},
 {"n":57,"ar":"وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ","tr":"İlk layihə tərcümə: İman gətirib saleh əməl edənlərə isə (Allah) onların əməllərinin mükafatını tam verəcəkdir; Allah zülm edənləri sevməz.","ex":"Tərcümə: Ayə iman və saleh əmələ görə mükafatın tam veriləcəyini və Allahın zülmkarları sevmədiyini bildirir. Şərh: Mətn sadə mükafat-məzmun prinsiplərini ifadə edir; burada “məhar” və “zülm” anlayışlarının məzmunu kontekstdən asılı ola bilər və əlavə izahat üçün başqa ayələrə baxmaq faydalıdır.","rel":"Əl-i İmran 3:56,58"},
 {"n":58,"ar":"ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْءَايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ","tr":"İlk layihə tərcümə: Bunları Biz sənə ayələr və hikmətli xatırlatma olaraq oxuyuruq.","ex":"Tərcümə: Ayə əvvəlkiləri Qurandan gələn ayələr və hikmətli bir xatırlatma kimi təqdim edir. Şərh: Bu, təqdim olunan məzmunun ilahi və hikmətli olduğu iddiasını vurğulayır; “hikmət” sözünün konkret sahəsi mətn daxilində məhduddur və müxtəlif aspektlərə işarə edə bilər.","rel":"Əl-i İmran 3:59-60"},
 {"n":59,"ar":"إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍۢ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ","tr":"İlk layihə tərcümə: Həqiqətən, İsanın Allah yanında misalı Adəmdir: Onu torpaqdan yaratdı, sonra ona “Ol” dedi və o oldu.","ex":"Tərcümə: Ayə İsanın yaradılışı ilə Adəmin yaradılışı arasında bir bənzətmə aparır və hər ikisinin yaradılmasının Allahın əmri ilə baş verdiyini bildirir. Şərh: Burada məqsəd yaradılışın əsasında ilahi hökmün dayandığını göstərməkdir; “misal” sözünün hansı nəticələr çıxarmaq üçün istifadə oluna biləcəyi mətn daxilində müxtəlif cür şərh edilə bilər.","rel":"Əl-i İmran 3:55-60"},
 {"n":60,"ar":"ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ","tr":"İlk layihə tərcümə: Bu, sənin Rəbbindən olan həqiqətdir; şübhə edənlərdən olma.","ex":"Tərcümə: Ayə əvvəlki bəyanatın Allahdan gələn həqiqət olduğunu təsdiqləyir və şübhə edənlərə qarşı xəbərdarlıq edir. Şərh: Bu yekun cümlə ayələrin etibarlılığını vurğulayır və oxuyana şübhəyə düşməməyi tövsiyə edir; “şübhə” və onun çərçivəsi mətn daxilində aydınlaşdırılır, lakin fərqli oxunuşlar mümkündür.","rel":"Əl-i İmran 3:59"},
 {"n":61,"ar":"فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ","tr":"Belə isə, sənə gələn elmə baxmayaraq bu barədə səninlə mübahisə edən olarsa, de: “Gəlin öz oğullarımızı və sizin oğullarınızı, öz qadınlarımızı və sizin qadınlarınızı, özümüzü və sizin özünüzü çağırıb dua edək, sonra da yalançılar üzərinə Allahın lənətini diləyək.”","ex":"İzah: Mətn mübahisəni həll etmək üçün qarşı tərəfi açıq bir məhkəməyə — uşaqlar, xanımlar və özlərinin iştirakı ilə dua və lanətlə məhkəmə etməyə dəvət edir. Şərh: Burada təsvir olunan tədbirin mahiyyəti və tətbiqi tarixi zəminə görə müzakirəyə açıqdır; ayə qarşı tərəfin ciddi bir sınağa çağırıldığını göstərir, amma tətbiq formaları barədə Quran özü detallar vermir.","rel":""},
 {"n":62,"ar":"إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","tr":"Həqiqətən, bu haqq sözdür. Allahdan başqa heç bir ilah yoxdur. Həqiqətən Allah Qüdrətlidir, Hikmət sahibidir.","ex":"İzah: Bu cümlə əvvəlki hadisəni ümumi şəkildə təsdiqləyir və vahid ilah ideyasını güclü şəkildə bəyan edir. Şərh: Ayədəki “haqq qissə” ifadəsi hadisənin doğru və ədalətli olduğunu vurğulayır; “Allahdan başqa ilah yoxdur” ifadəsi təvhidi mərkəzə qoyur.","rel":""},
 {"n":63,"ar":"فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ","tr":"Əgər onlar üz döndərsələr, bilin ki, Allah fəsad törədənlərin hallarını bilir.","ex":"İzah: Burada əks tərəf üz döndərsə — yəni dəvəti rədd etsə — Allahın onların əməllərini və niyyətlərini bildiyi qeyd olunur. Şərh: Bu ifadə insanların qərarlarının və nəticələrinin Allah qabağında bilinən olduğunu vurğulayır; ayə insanların məsuliyyətini xatırladır.","rel":""},
 {"n":64,"ar":"قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍۢ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًۭٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًۭا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ","tr":"De: “Ey Kitab əhli! Gəlin bizimlə sizin aranızda ortaq bir sözə gələk: yalnız Allahı ibadət edək, Ona heç nəyi şərik qoşmayaq və biri-birimizi Allahdan başqa əllahlar (müstəqil hökmranlar) etməyək.” Əgər üz döndərsələr, deyin: “Şahid olun ki, biz müsəlmanlarıq (təslim olmuşuq).”","ex":"İzah: Bu dəvət Kitab əhlini (Yəhudi və Xristianlara yönəlmiş) vahid inanc ətrafında həmrəylik çağırışıdır və müşrikliyə qarşıdır. Şərh: Ayədəki “ortaq söz” çağırışı dini dialoq və birlik üçün bir təşəbbüs kimi təqdim olunur; necə həyata keçiriləcəyi və qəbul olunma şərtləri barədə əlavə izahat verilməyib.","rel":""},
 {"n":65,"ar":"يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ","tr":"Ey Kitab əhli! Niyə İbrahimin əleyhinə mübahisə edirsiniz? Çünki Tövrat və İncil yalnız ondan sonra nazil edilmişdir. Axı düşünmürsünüz?","ex":"İzah: Mübahisə edən tərəflərə İbrahimin dövrü və Tövrat ilə İncilin onun sonrasına nazil olması xatırladılır; buna görə İbrahimin məqamı barədə mübahisə məntiqsiz sayılır. Şərh: Ayə tarixi ardıcıllığı əsas gətirərək mübahisənin tutarsızlığını göstərir, amma konkret məhkəmə qənaətini deyil, məntiqi sualı ortaya qoyur.","rel":""},
 {"n":66,"ar":"هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌۭ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌۭ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ","tr":"Budur, siz indi öz bildiyiniz şey barəsində mübahisə edirsiniz; bəs bilik sahibi olmadığınız şeylər barədə nə üçün mübahisə edirsiniz? Allah bilir, siz isə bilmirsiniz.","ex":"İzah: Ayə insanların bildiklərinə əsasən danışıb, bilmədikləri mövzularda mübahisə etmələrinin əleyhinə çıxır və bilikdə təvazö göstərilməsini tələb edir. Şərh: Burada “Allah bilir, siz bilməzsiniz” ifadəsi insan məhdudiyyətlərini və Allahın hər şeydən xəbərdar olduğunu vurğulayır; ayə eyni zamanda düşüncəyə çağırır.","rel":""},
 {"n":67,"ar":"مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّۭا وَلَا نَصْرَانِيًّۭا وَلَٰكِن كَانَ حَنِيفًۭا مُّسْلِمًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","tr":"İbrahimin yəhudi və ya xristian olmadığı açıqdır; o, əyrilikdən üz döndərmiş (hənif), təslim olmuş (müsəlman) idi və müşriklərdən deyildi.","ex":"İzah: Ayə İbrahimin dininin səciyyəsini — təkliyə yönələn və bütə tapınmadan uzaq ifadə edir. Şərh: “Hənif” və “müsəlman” kimi terminlər İbrahimin vahid Allaha yönəlmiş nisbi xarakterini göstərir; bu, tarixi və teoloji məzmunlu bir qiymətləndirmədir və mətnin özündən çıxarılan məna olaraq təqdim olunur.","rel":""},
 {"n":68,"ar":"إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ","tr":"İbrahimin ən yaxınları onun ardınca gedənlərdir, həmçinin bu peyğəmbər və iman gətirənlər də. Allah möminlərin dostudur (və himayədarıdır).","ex":"İzah: Ayə İbrahimin əsl varislərinin onu izləyənlər və iman edənlər olduğunu bildirir və Allahın möminlərə himayədarlığını bəyan edir. Şərh: Burada “ən yaxınlar” ifadəsi mənəvi və inanc baxımından yaxınlığı vurğulayır, geneoloji iddiaları və ya xüsusi nəsibliyi avtomatik təsdiqləmir; məna daha çox ruhani izahdadır.","rel":""},
 {"n":69,"ar":"وَدَّت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","tr":"Kitab əhli içərisində bir dəstə sizi azdırmaq istərdi; ancaq onlar yalnız özlərini azdırırlar və bunu hiss etmirlər.","ex":"İzah: Burada bəzi Kitab əhli nümayəndələrinin yanlış istiqamətə yönəltmə cəhdləri qeyd olunur, lakin nəticədə zərbə özlərinə dəyir. Şərh: Ayə insanların yanlışlıq içində olduqlarını və bunun fərqində olmadıqlarını bildirir; bu qiymətləndirmə konkret şəxslərə deyil, davranış və nəticələrə yönəlmişdir.","rel":""},
 {"n":70,"ar":"يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ","tr":"Ey Kitab əhli! Niyə Allahın ayələrini inkar edirsiniz, halbuki onları siz öz gözlərinizlə şahidlik edirsiniz?","ex":"İzah: Ayə Kitab əhli üzərinə, özlərinin gördükləri və tanıdıqları ilahi əlamətləri vəhylə əlaqələndirərək niyə inkar etdiklərini soruşur. Şərh: Burada sual vasitəsilə onların tutarsızlığı vurğulanır; ayə konkret səbəbləri göstərmir, yalnız müşahidə və etiraz arasındakı uyğunsuzluğa diqqət çəkir.","rel":""},
 {"n":71,"ar":"يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ","tr":"Ey Kitab əhli! Niyə həqiqəti batillə qarışdırırsınız və həqiqəti gizlədirsiniz, halbuki bilirsiniz?","ex":"Mətnin birinci cümləsi birbaşa çağırış və ittihaddır; burada Kitab əhli həm həqiqəti batillə qarışdırmaqda, həm də həqiqəti bilərəkdən gizlətməkdə ittiham edilir. Bu ifadə onların davranışını tənqid edir; hansı konkret faktların nəzərdə tutulduğu isə ayənin ümumi kontekstində qiymətləndirilir.","rel":"2:42, 3:78"},
 {"n":72,"ar":"وَقَالَت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ","tr":"Kitab əhlindən bir qrup dedi: “Gün ərzində (açıqca) möminlərə nazil olana inan, axırını isə inkar et; bəlkə onlar dönərlər.”","ex":"Bu cümlə Kitab əhlindən bəzi şəxslərin ikili davranışını göstərir — gündüz açıq iman, gecə isə örtülü inkar. Ayənin dəqiq mənası məsələsi: “gün” və “axır” ifadələrinin nəyi işarə etdiyi fərqli oxunuşlara açıqdır; burada davranışın zahiri və gizli tərəfləri vurğulanır.","rel":"3:71, 3:73"},
 {"n":73,"ar":"وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌۭ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ","tr":"(Bəziləri) deyir: “Yalnız sizin dininizi izləyənlərə iman gətirin.” De: “Həqiqətən hidayət Allahın hidayətidir. Mümkündürmü kimsəyə sizə verilən kimi verilə və ya Rəbbiniz yanında sizinlə mübahisə etsin?” De: “Fəzilət Allahın əlindədir; onu istədiyinə verir. Allah genişdir, biləndir.”","ex":"Burada Peyğəmbərə nə söylənməsi tələb olunur — iddialara cavab olaraq hidayətin qaynağının Allah olduğu və fəzlin O'nun istəyi ilə verildiyi vurğulanır. Bu ifadələr müqayisə və Allahın iradəsinin üstünlüyünü göstərir; konkret kimin nəyə layiq olduğu məsələsi ayədə qismən qalan bir sual olaraq qalır.","rel":"3:74, 3:71"},
 {"n":74,"ar":"يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","tr":"O Öz rəhməti ilə kiminə istəsə xas edir. Allah böyük fəzil sahibi və böyükdir.","ex":"Bu qısa ayə Allahın öz mərhəmətini kiminə verəcəyini seçməkdə sərbəst olduğunu bildirir. Bu, ilahi seçim və fəzil üzərində qısa təsnifatdır; ayə konkret meyarlardan danışmır, yalnız seçimin Allahın ixtiyarında olduğunu göstərir.","rel":"3:73, 3:76"},
 {"n":75,"ar":"۞ وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍۢ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍۢ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًۭا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّۦنَ سَبِيلٌۭ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ","tr":"Kitab əhlindən kiminsə üzərinə qintar etibar etsən, onu sənə qaytarar; bəzisi isə sənə dinar etibar etsən, yalnız sən üstünə dayanıb gözlədiyin müddətcə onu qaytarar. Bu, onların “ümmi insanlara yol yoxdur” demələrinə və Allah barəsində yalan söyləyib bilmələrinə görədir.","ex":"Bu ayə Kitab əhlindən fərqli davranış nümunələrini maddi məsuliyyət kontekstində göstərir və bəzi praktik haqsızlıqları işarə edir. “Ümmi” sözü və kontekstdəki səbəblərin izahı yorum tələb edir; ayə ümumi tənqid və müşahidə verir, konkret fərdlərin adını çəkmir.","rel":"2:79, 3:78"},
 {"n":76,"ar":"بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ","tr":"Bəli, kim əhdinə sadiq qalır və takva (Allaha qarşı ehtiyat) nümayiş etdirirsə, Allah mütəqiləri sevər.","ex":"Ayə iman və əhddə sədaqət olanları tərifləyir və takvanın Allahın sevgisinə səbəb olduğunu vurğulayır. Bu, davranış və əxlaq üzrə müsbət tövsiyəni ifadə edir; «Allah mütəqiləri sevər» sərt qiymətləndirici bir nəticədir, deyilənlərin ümumi mahiyyətini çatdırır.","rel":"3:77, 2:177"},
 {"n":77,"ar":"إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًۭا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْءَاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ","tr":"Həqiqətən, Allahın əhdini və andlarını az bir məbləğə satanlar həqiqətən axirətdə paya malik deyillər; Allah onlarla danışmaz, Qiyamət günü onlara baxmaz, onları paklamaz və onlar üçün ağrılı əzab vardır.","ex":"Burada əhd və andların satılması — yəni müqəddəs öhdəliklərin bir kənara qoyulması — ciddi nəticələrlə (axirətdə məhrumiyyət və cəza) bağlanır. Ayə şiddətli dini və əxlaqi məsuliyyəti vurğulayır; hansı əməl və ya dəyərin “satılma” sayıldığı bəzi hallarda izaha ehtiyac göstərə bilər.","rel":"3:76, 3:78"},
 {"n":78,"ar":"وَإِنَّ مِنْهُمْ لَفَرِيقًۭا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ","tr":"Onların bəzisi dillərini Kitabla əyərək onu kitabdanmiş kimi göstərməyə çalışar; halbuki o kitabdan deyildir. Onlar deyirlər: “Bu Allahdandır,” halbuki o Allahdan deyildir; onlar Allah barədə yalan söyləyirlər və bilirlər.","ex":"Ayə bəzi şəxslərin kitabdan parçaları çarpıdıb insanları səhv yönləndirməsinə işarə edir və onların səlahiyyətlərini sui-istifadə etdiklərini iddia edir. Bu, mətnin saxtalaşdırılması və yalançı iddiaların qınanması kimi başa düşülə bilər; hansı konkret mətnlərin nəzərdə tutulduğu ayə daxilində açıq deyil.","rel":"2:79, 3:71"},
 {"n":79,"ar":"مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًۭا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّۦنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ","tr":"İnsana Allahın Kitabı, hökmü və nübüvvəti verməsi və sonra insanlara “Mənə Allahdan başqa qullar olun” deməsi mümkün deyil. Əksinə, onlar öyrətdiklərinizlə və öyrəndiklərinizlə “rabbaniyyun” olsunlar.","ex":"Bu ayə peyğəmbər və alim mövqeyinin məqsədini izah edir: vəzifə insanları Allaha yönləndirmək, özlərinə ilah etməyə çağırmaq deyil. Burada “rabbaniyyun” termini xüsusi dini öyrənmə və müəllimlik statusunu ifadə edir; onun dəqiq tərcüməsi və tətbiqi fərqli oxunuşlara açıqdır.","rel":"3:80, 3:79"},
 {"n":80,"ar":"وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّۦنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ","tr":"O sizə mələkləri və peyğəmbərləri rablər (ilahlar) tutmağı əmr etməz. Onlar siz müsəlman olduğunuz halda sizi küfrəmi çağırarlar?","ex":"Ayə vurğulayır ki, haqqı gətirən şəxs başqalarını mələk və peyğəmbərləri ilah kimi qəbul etməyə çağırmaz. Son cümlə iddianın məntiqi olmadığını sorğulayır; burada müzakirə edilən davranışın məntiqi və dini ziddiyyəti göstərilir.","rel":"3:79"},
 {"n":81,"ar":"وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّۦنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍۢ وَحِكْمَةٍۢ ثُمَّ جَآءَكُمْ رَسُولٌۭ مُّصَدِّقٌۭ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ","tr":"(Xatırlayın ki) Allah peyğəmbərlərin əhdini aldığı vaxt: “Sizə verdiyim Kitab və hikmətə görə — sonra yanınıza gətiriləcək və sizinlə olanı təsdiq edəcək bir Rəsul gələcək; siz Ona iman edəcək və Ona yardım edəcəksiniz” dedi. “Buna razısınız və bununla bağlı mənim əhdimi qəbul edirsinizmi?” — Onlar “Razıyıq” dedilər. O isə “Onda şahid olun; Mən də sizinlə şahidlərdənəm” buyurdu.","ex":"Tərcümə: Ayə Allahın peyğəmbərlərə verdiyi kitab və hikmətə dair bir əhdin olduğunu və gələcəkdə onların yanına gələcək bir Rəsula iman edib ona yardım edəcəklərinin tələb edildiyini bildirir. Təfsir: Mətndən çıxan məna budur ki, peyğəmbərlərlə alınan bu əhd gələcək bir rəsulun qəbuluna dair ümumi bir öhdəlik kimi təqdim olunur; “əhd” və “şəhadət” ifadələrinin konkret məzmunu mətn daxilində açıq-aydın verilməyib, buna görə müəyyən detalları dəqiq söyləməkdən çəkinmək lazımdır.","rel":"3:82-85"},
 {"n":82,"ar":"فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ","tr":"Buna sonra üz çevirənlər isə fasiqlərdir.","ex":"Tərcümə: Bu ayə deyir ki, əvvəlcə götürülən əhdə sonra xəyanət edənlər fasiq sayılacaqlar. Təfsir: “Fasiq” burada əhdə və ilahi tələblərə qarşı itaətsiz, üz çevirən insanları təsvir edir; ayə konkret şəxsləri sadalamaqdan çox ümumi bir xəbərdarlıq verir.","rel":"3:81,3:83-90"},
 {"n":83,"ar":"أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا وَإِلَيْهِ يُرْجَعُونَ","tr":"Onlar Allahın dinindən başqa bir din axtarırlar? Göylərdə və yerdə olanların hamısı könüllü və ya məcburi Ona təslim olmuşdur və Ondan başqasına qaytarılmayacaqlar.","ex":"Tərcümə: Ayə Allahın dinindən başqa din axtaranları sual edir və bildirir ki, göylərdə və yerdə olanlar həm könüllü, həm də istəsələr də istəməsələr də Ona təslim olmuşlar və Ona qayıdırlar. Təfsir: “Təslim olmaq” ifadəsi burada nihai hesaba və hakimiyyətə tabe olma mənasında istifadə olunur; mətndəki “könüllü və ya məcburi” ifadəsi hamının nəhayətində İlahi hakimiyyət qarşısında olacağına işarə edir.","rel":"3:84-85"},
 {"n":84,"ar":"قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ","tr":"De: “Biz Allaha, bizə nazil edilənə və İbrahiminə, İsmailinə, İshaqına, Yaqubuna və onların nəsillərinə, Musaya və İsaya və Rəbblərinin göndərdiyi digər peyğəmbərlərə iman etdik. Onların heç birini bir-birindən ayırmırıq və Biz Ona təslik olmuşuq.”","ex":"Tərcümə: Bu ayə inananların Allahı və Ona nazil edilmiş kitabları, həmçinin bir sıra ötən peyğəmbərləri rədd etmədən qəbul etdiklərini bəyan edir. Təfsir: Mətndən belə başa düşülə bilər ki, burada vurğulanan davamlılıq və peyğəmbərlər arasında ayrı-seçkilik etməməkdir; bu, möminliyin ümumi etiqad istiqamətini ifadə edir rather than specifying doctrinal nüansları.","rel":"3:85-86"},
 {"n":85,"ar":"وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًۭا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ","tr":"Kim Allah yolundan (Onun əmr etdiyi təslimçilikdən) başqa bir din axtararsa, onun dinindən qəbul edilməyəcək və o, axirətdə ziyana uğrayanlardandır.","ex":"Tərcümə: Ayə deyir ki, Allahın istədiyi təslimçilikdən başqa yol seçənlərin bu seçimi qəbul edilməyəcək və onlar axirətdə məğlub olarlar. Təfsir: Burada “İslam” sözü “Allaha təslim olmaq” mənasında istifadə olunur; ayənin konkret tətbiqi və hansı hallarda qəbulun rədd ediləcəyi mətndəki ümumi xəbərdarlıq çərçivəsində verilir.","rel":"3:84,3:86-90"},
 {"n":86,"ar":"كَيْفَ يَهْدِى ٱللَّهُ قَوْمًۭا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّۭ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ","tr":"Allah imanlarına xəyanət edib sonra kafir olmuş, Rəsulun haqq olduğunu gördüklərinə şahidlik edərək onlara aydın dəlillər gəldikdən sonra necə onları hidayət etsin? Allah zülm edənləri doğru yola yönəltməz.","ex":"Tərcümə: Ayə sual formasında bildirir ki, imandan sonra küfrə qayıdan və Rəsulun haqq olduğunu görənlərə necə hidayət verilə bilər; nəticə olaraq Allah zülm edənləri doğru yola yönəltməz. Təfsir: Burada vurğu davamlı rədd və zülm halının nəticələrinə yönəlib; “zülm edənlər” anlayışının dəqiq sərhədləri mətndə fərqli kontekstlərdə mühakimə tələb edə bilər.","rel":"3:81-85,3:87-90"},
 {"n":87,"ar":"أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ","tr":"Onların mükafatı budur: üzərilərinə Allahın, mələklərin və bütün insanların lənəti düşəcəkdir.","ex":"Tərcümə: Ayə bildirir ki, əksəriyyətlə rədd edənlərin əvəzində Allahın, mələklərin və insanların lənəti olacaq. Təfsir: “Lənət” ifadəsi burada şiddətli ilahi məhkumiyyəti və ümumi rədd edilməyi göstərir; bu xəbərdarlıq mətnin davamındakı digər ayələrdə verilən nəticələrlə bağlıdır.","rel":"3:88-90"},
 {"n":88,"ar":"خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ","tr":"Onlar orada əbədi qalacaqlar; onların əzabı yüngülləşdirilməyəcək və onlara vaxt verilməyəcək.","ex":"Tərcümə: Ayə deyir ki, bu cür insanların cəzası orada əbədi olacaq, azaldılmayacaq və onlara əlavə müddət verilməyəcək. Təfsir: Mətndə “əbədi qalmaq” və “əzabın yüngülləşdirilməməsi” kimi ifadələr güclü xəbərdarlıq rolunu oynayır; konkret istisnalar və detalları ayələr arasında müqayisə tələb edir.","rel":"3:87,3:89-90"},
 {"n":89,"ar":"إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ","tr":"İstisna olaraq, bundan sonra tövbə edənlər və düzələnlər ayrı tutulur; çünki Allah bağışlayan və rəhm edəndir.","ex":"Tərcümə: Ayə həmin qruplardan sonra tövbə edib özünü düzəldənlərin fərqli olduğunu və Allahın bağışlayıcı və rəhmli olduğunu bildirir. Təfsir: Burada vurğulanır ki, davamlı olmayan səmimi tövbə və düzəliş mümkündür və bu hal mətnə görə rəhmə gətirib çıxara bilər; tövbənin qəbul olunmasının şərtləri mətn daxilində tam detallandırılmayıb.","rel":"3:87-90"},
 {"n":90,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًۭا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ","tr":"Həqiqətən, iman etdikdən sonra kafir olub daha da küfrü artıranların tövbəsi qəbul edilməyəcək və onlar azıq düşənlərdir.","ex":"Tərcümə: Ayə xəbər verir ki, imandan sonra küfrə qayıdıb bununla da küfrlərini artıranların tövbələri qəbul edilməyəcək və onlar doğru yoldan çıxmış hesab ediləcəklər. Təfsir: Mətndə 89-cu ayənin tövbə üçün bir istisna göstərməsi ilə 90-cı ayənin sərt xəbərdarlığı arasında görünən gərginlik var; bunu bu iki ayə birlikdə oxuyarkən tövbənin səmimiyyəti, davamlılığı və üz çevirilməmə kimi şərtlərlə bağlı olduğu kimi başa düşmək olar, lakin mətn özündə bu şərtlərin bütün detalları barədə açıq hökm vermir.","rel":"3:89,3:81-88"},
 {"n":91,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌۭ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًۭا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ وَمَا لَهُم مِّن نَّٰصِرِينَ","tr":"Həqiqətən, kafir olan və kafir olaraq ölmüş olanlardan heç birinin bütün yer üzünün miqdarı qızıl olsa belə, onun üçün qəbul edilməyəcək; hətta onunla fidyə versə belə. Onların üçün əzablı bir əzab var və onların heç bir köməkçisi yoxdur.","ex":"Tərcümədə «məlʾu al-ard» ifadəsi «bütün yer üzünün miqdarı» kimi verilib; ayə maddi zənginliyin belə əslində fayda verməyəcəyini bildirir. Bu, Quran daxili kontekstdə imanın və tərbiyənin maddi fidyədən üstünlüyünü göstərən bir xəbərdarlıq kimi başa düşülə bilər (şərhidir, tam təhlükəsizlik tələb etmir).","rel":"3:90-92"},
 {"n":92,"ar":"لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌۭ","tr":"Siz xeyri (birri) əldə etməyincə sevdiyiniz şeylərdən xərcləməzsiniz. Və nə isə xərcləsəniz, Allah onun barəsində biləndir.","ex":"«Birr» sözü burada ümumi xeyirli davranış və salehlik mənasında tərcümə edilib; bəzən şərhlərdə daha konkret olaraq xeyriyyə və yardımla bağlı izah olunur. Ayə Quranın ümumi öyrədiciliyinə uyğun olaraq sevib bağlandığınız şeylərdən könüllü xərcləmənin iman və əxlaq baxımından vacibliyini vurğulayır (şərhidir).","rel":"3:91,2:261"},
 {"n":93,"ar":"۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ","tr":"Bəqərənin övladları üçün hər növ qida halal idi, məhz İsrail özündən əvvəl özü üçün haram etdikləri istisna olmaqla — Tövrət nazil olmamışdan əvvəl. De: «Əgər doğrusunuzsa, Tövrəti gətirin və onu oxuyun».","ex":"Ayə burada «İsrail» adlanan şəxsin (Yaqqubun ləqəbi kimi Quran mətnində) özündən əvvəl bəzi qidaları özünə haram etməsini göstərir; tərcümə bunu mətnə sadiq şəkildə əks etdirir. «Tövrət gətirin və onu oxuyun» deməkdə məsələni sübut etməyə çağırmaq vardır; bu, Quranın daxili diskursunda mübahisəni sənəd göstərməklə nizamlayıcı tərzdə davam etdirmə tələbi kimi başa düşülə bilər (şərhidir).","rel":"3:94-95"},
 {"n":94,"ar":"فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","tr":"Sonradan Allah haqqında yalan uyduran kimsə isə zalimlərdəndir.","ex":"Tərcümə sözün gözlə görünən mənasına uyğundur; ayə əvvəlki cümlədəki tələbə əməl etməyib Allah barədə yalan uyduranları qınayır. Bu, Quran daxilində hökm və məhkumiyyət bəyanıdır; kiminsə uydurma ilə məhz Quranın irəli sürdüyü ölçüləri pozduğu vurğulanır (şərhidir).","rel":"3:93-95"},
 {"n":95,"ar":"قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","tr":"De: «Allah haqqdır.» İbrahimin dinini (millətini) düz olaraq izləyin; o müşriklərdən deyildi.","ex":"«Ibrahimin milləti» ifadəsi burada onun yolunu izləmək çağırışıdır; «hənif» sözü «düz, əyilməyən» məna verir və tərcümədə buna uyğun verilib. Ayə Quran daxilində İbrahimə tabe olmağı iman əhəmiyyətində nümunə göstərir; bu, mətnin özündən çıxarılan tövsiyədir (şərhidir).","rel":"3:93-96"},
 {"n":96,"ar":"إِنَّ أَوَّلَ بَيْتٍۢ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًۭا وَهُدًۭى لِّلْعَٰلَمِينَ","tr":"Həqiqətən, insanlara yönəldilmiş ilk ev Bakıkkada (Bəkkədə) qoyulmuşdur — xeyirli və aləmlər üçün bir hidayət.","ex":"«Bəkkə» adı mətnin özündə verilib; tərcümə onu saxlayır və «ilk ev» ifadəsi müqəddəs vəsaitin ilkin quruluşuna işarə edir. Ayə burada o məkânın xeyirli və bəşəri hidayət funksiyasını vurğulayır; qeyd etmək lazımdır ki, mətn özü bu atributları verir (şərhidir).","rel":"3:97"},
 {"n":97,"ar":"فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌۭ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًۭا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ","tr":"Orada aşkar ayələr, İbrahimin Məqamı vardır; və onu kim daxil olarsa, təhlükəsizdir. Allahın insanlar üzərinə hökmdarlığı budur ki, imkan tapanlar üçün Bizim evimizin həcci ona çatana bir vəzifədir; kəfir olanlara gəlincə, Allah aləmlərə möhtac deyildir.","ex":"«Maqam İbrahimin» ifadəsi mətndə xüsusi bir yerdən bəhs edir; «kimin daxil olarsa təhlükəsizdir» cümləsi o məkanın təmin etdiyi təhlükəsizlik hissinə işarə edir. Ayə həm ritual məsuliyyəti (həccin öhdəlik olduğu), həm də kafirlik halında Allahın Onun yaratdıqlarından müstəqil olduğunu bildirir; bu izah Quranın kontekstindən çıxarılan interpretasiyadır.","rel":"3:96,2:196"},
 {"n":98,"ar":"قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ","tr":"De: «Ey Kitab əhli! Allahın ayələrinə niyə inkar edirsiniz?» Allah sizin etdiklərinizə şahiddir.","ex":"Bu tərcümə sual formasını və Allahın şahidliyini sadə şəkildə verir. Ayə müzakirə üslubunda Kitab əhlinə ünvanlanmış sual formasıdır; burada onların inkarı və Allahın hərəkətlərə şahidliyi bir-birinə qarşı durur — bu, mətndən çıxarılan müşahidədir (şərhidir).","rel":"3:99-100"},
 {"n":99,"ar":"قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًۭا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ","tr":"De: «Ey Kitab əhli! Siz iman gətirənləri Allah yolundan niyə çəkirsiniz? Onu əyri etmək istəyirsiniz; halbuki siz şəhadət verənlərsiz. Allah etdiklərinizdən gafil deyildir.»","ex":"Tərcümə «səbəbb verib» və «əyri etmək» ifadələrini mətndəki mənaya uyğun təqdim edir. Ayə burada Kitab əhlinin iman edənləri haqq yolundan yayındırmaq cəhdini və Allahın onların əməllərindən xəbərdar olmasını qeyd edir; bu, mətnin özündən çıxan bir tənqid kimi başa düşülə bilər (şərhidir).","rel":"3:98-100"},
 {"n":100,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًۭا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ","tr":"Ey iman gətirənlər! Əgər Kitab verilənlərin bir qrupuna tabe olsanız, onlar sizi imanınızdan sonra kafirlərə qaytararlar.","ex":"Tərcümə «rəddukûm» ifadəsini «sizi geri qaytararlar» kimi verir; kontekstdə bu, dini mövqeyin dəyişdirilməsi və ya iman itkisilə nəticələnə biləcək təsir mənasına gəlir. Ayə iman edənlərə xəbərdarlıq edir ki, kitab əhli içində bəzi qrupların rəhbərliyi imanlarını pozmağa səbəb ola bilər — bu, ayədən çıxarılan ehtiyyat tövsiyəsidir (şərhidir).","rel":"3:99"},
 {"n":101,"ar":"وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","tr":"(ilk layihə) Necə küfr edirsiniz, halbuki Allahın ayələri sizə oxunur və sizin arasında Onun elçisi dədir? Kim Allahın ipinə yapışarsa, şübhəsiz doğru yola yönəldilmişdir.","ex":"Tərcümə: Ayə küfr edənlərin vəziyyətinə diqqət çəkir və möminlərin onlara üstünlüyünü vurğulayır. Şərh: \"Allahın ipi\" ifadəsi Allaha bağlılıq, vahid dini və ya Onun göstərişlərinə sıx yapışmaq anlamında başa düşülə bilər; bu, düz yolun tapılması ilə əlaqələndirilir. Bu şərh tərcümədən ayrı, məna dairəsini aydınlaşdırmaq üçündür və fərqli izahlar mümkündür.","rel":"3:103"},
 {"n":102,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ","tr":"(ilk layihə) Ey iman edənlər! Allahı haqqıyla qoruyun və yalnız müsəlman olaraq (Allaha təslim halda) vəfat edin.","ex":"Tərcümə: Ayə iman edənlərə Allah qarşısında haqqıyla təqva göstərməyi və ölümlərinə qədər təslimiyyət vəziyyətində olmağı tövsiyə edir. Şərh: \"Allahı haqqıyla qorxmaq\" səmimi əqidə və müvafiq əməl ardıcıllığını, \"müsəlman olaraq ölmək\" isə həyatın sonuna qədər imanın və itaətin saxlanmasını vurğulayır; bu ifadələrin konkret tətbiqi fərqli yanaşmalara açıqdır.","rel":"3:101,3:110"},
 {"n":103,"ar":"وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءًۭ فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًۭا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍۢ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ","tr":"(ilk layihə) Hamınız birlikdə Allahın ipinə yapışın və parçalanmayın. Allahın sizə olan nemətini xatırlayın: əvvəlcə düşmən idiniz, O ürəklərinizi birləşdirdi və Onun neməti ilə qardaş oldunuz; siz oddan bir uçurumun kənarında idiniz, O sizi oradan xilas etdi. Allah belə ayələrini sizə izah edir ki, bəlkə doğru yola yönəldəsiniz.","ex":"Tərcümə: Ayə birlik, Allahın neməti və xilas barədə məlumat verir. Şərh: \"Allahın ipi\" birliyi və vahid dini, düşmənlikdən qardaşlığa keçid isə Allahın mərhəmətini ifadə edə bilər; \"izah etmə\" sözü təlim və dəlillə yönəltmə məqsədini göstərir. Bu şərhlər tərcümədən ayrı durur və müxtəlif mənalandırmalar mümkündür.","rel":"3:104,3:101"},
 {"n":104,"ar":"وَلْتَكُن مِّنكُمْ أُمَّةٌۭ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","tr":"(ilk layihə) Sizin içinizdən bir ümmət olsun ki, yaxşılığa dəvət etsin, mə'rufu əmr etsin və pislikdən çəkindirsin; onlar müvəffəq olanlardır.","ex":"Tərcümə: Ayə möminlərdən müəyyən bir qrupun yaxşı işə çağırmasını, yaxşılığı təşviq edib pislikdən çəkindirməsini tələb edir. Şərh: Bu çağırış həm icma daxilində məsuliyyət, həm də ictimai funksiyanı bildirə bilər; \"uğur\" burada bu vəzifəni yerinə yetirənin mənəvi nəticəsinə işarə edir. Müəyyən terminlərin tətbiqi müxtəlif səviyyələrdə şərh edilə bilər.","rel":"3:103,3:110"},
 {"n":105,"ar":"وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌۭ","tr":"(ilk layihə) Aydın dəlillər sizə gəldikdən sonra parçalanıb ixtilaf edənlər kimi olmayın; onlar üçün böyük əzab vardır.","ex":"Tərcümə: Ayə möminləri dəfələrlə təsdiqlənmiş dəlillərdən sonra bölünənlərə bənzəməməyə çağırır. Şərh: \"Aydın dəlillər\" ifadəsi istiqamət verici və təsdiqedici vəhyə işarə edə bilər; \"böyük əzab\" isə xəbərdarlıq və nəticə ilə bağlıdır. Məna fərqli kontekstlərdə müxtəlif şəkildə başa düşülə bilər və bu, mütləq həqiqət kimi təqdim edilmir.","rel":"3:101,3:103"},
 {"n":106,"ar":"يَوْمَ تَبْيَضُّ وُجُوهٌۭ وَتَسْوَدُّ وُجُوهٌۭ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ","tr":"(ilk layihə) Bir gün üzlər ağaracaq və üzlər qaralacaq. İmanı saxladıqdan sonra küfr edənlərə deyiləcək: “Siz imanınızdan sonra necə küfr etdiniz? İndi küfr etdiyiniz üçün əzabı dadın.”","ex":"Tərcümə: Ayə Qiyamət günündə rasional və emosional fərqləri ifadə edən iki-halət—xilasedici və məhkumedici—haqqında xəbər verir. Şərh: \"Ağaran\" və \"qaralan\" üzü simvolik olaraq xoşbəxtlik və bədbəxtlik, xilas və cəza mənasında başa düşmək olar; ifadə esxatoloji xəbərdarlıqdır və konkret detalları müxtəlif cəhətlərdən şərh etmək olar.","rel":"3:107,3:108"},
 {"n":107,"ar":"وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ","tr":"(ilk layihə) Ağarmış üzlülər isə Allahın rəhmətindədirlər və orada əbədi qalacaqlar.","ex":"Tərcümə: Ayə ağarmış üzlü insanların Allahın mərhəmətində dayanacağını və orada əbədi qalacaqlarını bildirir. Şərh: \"Ağarmış üz\" rahatlıq və xilası, \"rəhmət\" isə mükafat və şərəf ilə bağlıdır; bu ifadələr geniş mənalıdır və fərqli izahları mümkündür.","rel":"3:106,3:108"},
 {"n":108,"ar":"تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعَٰلَمِينَ","tr":"(ilk layihə) Bunlar Allahın ayələridir; biz onları sənə haqq olaraq oxuyuruq. Allah isə aləmlərə qarşı zülm etmək istəməz.","ex":"Tərcümə: Ayə oxunan sözlərin Allahın ayələri olduğunu təsdiqləyir və Allahın zalimlik istəmədiyini bəyan edir. Şərh: \"Haqq\" sözü burada həqiqət və dürüstlüklə oxunuşu göstərir; Allahın zülm etməməsi İlahinin ədalət və rəhmət xüsusiyyətinə işarədir. Bu, ümumi prinsipi ifadə edir və spesifik hüquqi detalları izah etmir.","rel":"3:109,3:106"},
 {"n":109,"ar":"وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ","tr":"(ilk layihə) Gökdə və yerdə nə varsa hamısı Allaha məxsusdur; və işlərin hamısı Allaha qaytarılacaqdır.","ex":"Tərcümə: Ayə kainatın sahibi olaraq Allahın bütün nəfs və varlıqların malik olduğunu və işlərin son hesabının Allaha dönəcəyini bildirir. Şərh: Bu, sahibliyin və məsuliyyətin Allahda yekunlaşdığını vurğulayır; konkret nəticələr və mühakimə yalnız Allahın domeninə aid edilir. Müxtəlif təfsirlərdə bu ümumi prinsip müxtəlif nüanslarla izah oluna bilər.","rel":"3:108,6:12"},
 {"n":110,"ar":"كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًۭا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ","tr":"(ilk layihə) Siz insanlar üçün çıxarılan ən yaxşı ümmət oldunuz: yaxşılığa əmr edir, pislikdən çəkindirir və Allaha inanırsınız. Əgər Kitab əhli iman gətirsəydi, bu onların üçün daha yaxşı olardı; onlardan bəziləri möminlərdir, lakin çoxu fasiqdir.","ex":"Tərcümə: Ayə mömin ümmətin vəzifəsini və ona verilən tərifi bildirir, həmçinin Kitab əhli ilə bağlı şərti müşahidə edir. Şərh: \"Ən yaxşı ümmət\" ifadəsi həm məsuliyyət, həm də nümunəkarlıq fikrini ehtiva edir; Kitab əhlinin iman gətirməməsi isə bir imkanın əldən verildiyini göstərən xəbərdarlıqdır. Bu cümlələrdəki qiymətləndirmələr və təriflərin geniş təfsiri müxtəlif yanaşmalara açıqdır.","rel":"3:103,3:104"},
 {"n":111,"ar":"لَن يَضُرُّوكُمْ إِلَّآ أَذًۭى ۖ وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ","tr":"Onlar sizə yalnız bir az əziyyət verə bilərlər; əgər sizinlə döyüşsələr, arxalarını çevirib qaçarlar və onlara daha sonra kömək olunmaz.","ex":"Tərcümə: ayə düşmənin davamlı zərər vermək qüdrətinin məhdud olduğunu bildirir. Təfsiri: burada düşmənin əslində qorxaq olduğu və münaqişədə qalıcı üstünlük qazana bilməyəcəyi vurğulanır; bu, qarşı tərəfin nəticədə yardım görməyəcəyi ilə bitir.","rel":"3:111-120"},
 {"n":112,"ar":"ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍۢ مِّنَ ٱللَّهِ وَحَبْلٍۢ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍۢ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","tr":"Onların üstünə alçaldılma (şərəfsizlik) qoyuldu; harada olsalar məğlub edilmişdilər — istisna olaraq 'Allahın bir bağı' və 'insanların bir bağı' ifadəsi qeyd olunur — və Allahın qəzəbi onlara dəydi, yoxsulluq onlara çatdı. Bu, onların Allahın ayələrini inkar etmələri və (haqsız olaraq) peyğəmbərləri öldürmələri səbəbindəndir; beləliklə onlar asi və təcavüzkar oldular.","ex":"Tərcümə: ayə bir qövmün üzərinə gələn alçaldılma, Allahın qəzəbi və maddi çətinlikdən bəhs edir. Təfsiri: \"بِحَبْلٍ مِنَ اللَّهِ وَحَبْلٍ مِنَ النَّاسِ\" ifadəsinin mənası müxtəlif şəkildə şərh olunur; burada mətnin özü saxlanılır və bu frazanın təfsiri haqqında müəyyənlik bildirilmir.","rel":"3:111-120"},
 {"n":113,"ar":"۞ لَيْسُوا۟ سَوَآءًۭ ۗ مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌۭ قَآئِمَةٌۭ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ","tr":"Onlar bərabər deyillər. Kitab əhlindən bir camaat var ki, gecənin bir hissəsində Allahın ayələrini oxuyur və səcdə etdikdədirlər.","ex":"Tərcümə: ayə Kitab əhli içində hamısının eyni olmadığını bildirir. Təfsiri: burada xüsusi bir qrupun ibadət və zikr baxımından sədaqətli olduğu vurğulanır; bu, ümumi mühakimədən ayırma edən bir qeyd kimi verilib.","rel":"3:113-115"},
 {"n":114,"ar":"يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ","tr":"Onlar Allaha və axirət gününə inanır, yaxşılığı əmr edib pislikdən çəkindirir və yaxşı işlərdə bir-biri ilə yarışırlar; onlar salehlərdən (yaxşı əməl sahiblərindən)dirlər.","ex":"Tərcümə: ayə həmin camaatın iman və əxlaqi davranışlarını sadalayır. Təfsiri: bu xüsusiyyətlər salehlik göstəriciləri sayılır; ayə onların ictimai fayda üçün çalışmaqlarını önə çəkir.","rel":"3:113-115"},
 {"n":115,"ar":"وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍۢ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ","tr":"Onların etdiyi hər hansı yaxşılıq boşa çıxarılmayacaq; Allah təqvalıları yaxşı bilir.","ex":"Tərcümə: ayə yaxşı işlərin dəyərsizləşdirilməyəcəyini bəyan edir. Təfsiri: burada edilən yaxşı əməllərin tanınacağı və Allahın təqvalıların halını bildiyi vurğulanır; bu, əməlin Allah yanında qeyd olunacağına dair təminatdır.","rel":"3:114-116"},
 {"n":116,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَٰلِدُونَ","tr":"İnanmayanların malları da, uşaqları da Allah yanında onlara heç fayda verməyəcəkdir; onlar odda olanlardır və orada əbədi qalacaqlar.","ex":"Tərcümə: ayə imansızların qəzası və bunun nəticələrinin boşa çıxacağını bildirir. Təfsiri: burada maddi vasitələrin axirətdə heç bir kömək etməyəcəyi vurğulanır və bu, xəbərdarlıq kimi təqdim edilir.","rel":"3:116-117"},
 {"n":117,"ar":"مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍۢ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍۢ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ","tr":"Bu dünyada xərclədiklərinin misalı belədir: içində dağıdıcı tufan olan bir külək kimi, o tufan özlərinə zülm edən bir qövmün əkinini məhv etdi. Allah onlara zülm etmədi, onlar özlərinə zülm etdilər.","ex":"Tərcümə: ayə dünya malına sərf olunanı küləkdəki dağıntıya bənzədir. Təfsiri: burada vurğulanan məqam odur ki, özlərini məhv edən davranışlar nəticədə faydasız olur; ayə Allahın zülmkar olmadığı, insanların öz hərəkətləri ilə zərər çəkdiyi qənaətini verir.","rel":"3:117-118"},
 {"n":118,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ","tr":"Ey iman gətirənlər! Özünüzdən olmayanları içdən-dost (müxalifdən olan sıx dost) seçməyin; onlar sizə heç bir zərərdən çəkinməz və sizin çətinlik arzuladığınız vaxtı istəyirlər. Nifrətləri sözlərindən açıqca görünmüşdür, qəlblərində isə daha böyük nifrət vardır; Biz ayələri sizə açıqlamışıq, əgər ağıllısınızsa.","ex":"Tərcümə: ayə yaxın dostluq və məsləhətçi seçimi barədə xəbərdarlıq edir. Təfsiri: \"بِطَانَةً مِن دُونِكُمْ\" ifadəsinin məzmunu mətndə məntiq çərçivəsində verilir; burada yad qruplardan daxili dəstək gözləməmək və onların niyyətlərinə diqqət etmək tövsiyə olunur.","rel":"3:118-120"},
 {"n":119,"ar":"هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","tr":"Baxın, siz onları sevirsiniz, onlar isə sizi sevmirlər. Siz Kitaba tam inanırsınız; qarşılaşdıqda 'iman etdik' deyirlər, amma tək qaldıqları zaman qəzbdən barmaqlarını dişləyirlər. De: Qəzəbdən ölməklə ölüb gedin; Allah qəlblərin içini yaxşı bilir.","ex":"Tərcümə: ayə qarşılıqsız məhəbbət və namizədlərin gizli nifrətini təsvir edir. Təfsiri: \"مُوتُوا بِغَيْظِكُمْ\" sözünün birbaşa mənası verilir; burada möminlərə xitabən, məhəbbətləri qarşılıq tapa bilmədikdə soyuqqanlı qalmaq və Allahın niyyətləri bildiyini unutmamaq tövsiyə olunur.","rel":"3:118-120"},
 {"n":120,"ar":"إِن تَمْسَسْكُمْ حَسَنَةٌۭ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌۭ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌۭ","tr":"Sizə yaxşılıq dəyəndə onlar bunu sevməzlər, sizə pislik gəldikdə isə onunla sevinərlər. Siz səbir edib taqva göstərsəniz, onların hiyləsi sizə heç bir zərər verməz. Həqiqətən, Allah onların etdiklərini əhatə edəndir.","ex":"Tərcümə: ayə düşmənlərin ikiüzlü reaksiya modellərini göstərir və möminlərə səbir/təqvaya çağırır. Təfsiri: burada vurğu odur ki, səbir və təqva onların hiylələrini əksər hallarda mənasız edər və Allahın onların əməllərini bilib nəzarət etdiyi qeyd olunur.","rel":"3:111-120"},
 {"n":121,"ar":"وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","tr":"Və xatırladığın zaman evindən səhərə çıxıb möminlərə döyüş üçün mövqelər təyin edirdin. Allah eşidəndir, biləndir.","ex":"Tərcümə: Bu ayə bir hadisəni—sənin (Peyğəmbərin) evdən çıxıb möminlərə döyüş yeri hazırlamağını—ifadə edir və Allahın eşidən və bilən olduğunu xatırladır. Şərh: Mətn hadisənin təşkilini və Allahın nəzarətini vurğulayır; konkret tarixi detalları və ya motivləri yalnız Qurandakı mətn əsasında təfsir etmək lazımdır.","rel":"3:122-126"},
 {"n":122,"ar":"إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ","tr":"O zaman sizdən iki qrup darmadağın olmaq üzrə idi; Allah onların Məvlası idi. Möminlər isə Allaha təvəkkül etməlidirlər.","ex":"Tərcümə: Ayə iki qrupun çətin vəziyyətdə olduğunu və Allahın onların müdafiəçisi olduğunu bildirir. Şərh: Burada “həmmət” və “təvəkkül” anlayışları möminlərin əqidə və ruh halına işarə edir; “iki qrup”un kimliyi və nə dərəcədə geri çəkildikləri barədə mətn özü mübahisəlidir və dəqiq nəticə üçün başqa mətnə istinad tələb olunur.","rel":"3:121-125"},
 {"n":123,"ar":"وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍۢ وَأَنتُمْ أَذِلَّةٌۭ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ","tr":"Şübhəsiz, Allah sizi Bədrdə yardım etdi, halbuki siz zəif idiniz. Ona görə də Allahdan qorxun ki, şükür edəsiniz.","ex":"Tərcümə: Ayə Bədr döyüşündə Allaha xatirə gətirir və o vaxtların şərtləri—möminlərin zəifliyi—xatırlanır. Şərh: Mətn Allaha təşəkkür və qorxu (təqva) çağırışı edir; “zəif” sözü həm maddi, həm də nisbətən haqlı mənada başa düşülə bilər və konkret qiymət yalnız Qurani-Kərim çərçivəsində qalır.","rel":"8:9;3:121-126"},
 {"n":124,"ar":"إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ","tr":"(Unutmayın o vaxt) sən möminlərə demişdin: “Sizin Rəbbinizin sizi göndərəcəyi üç min mələyin enməsi sizin üçün yetərli olmazmı?”","ex":"Tərcümə: Ayədə Peyğəmbərin möminlərə mələk dəstəyi barədə danışdığı göstərilir və mətn üç min mələkdən bəhs edir. Şərh: Burada qeyd edilən rəqəm mətnin özündə var; “mələk dəstəyi”nin təbiəti və necə baş verdiyi barədə mətnin özü xaricində şərh vermək məhduddur.","rel":"8:9;8:10"},
 {"n":125,"ar":"بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ","tr":"“Bəli!”—əgər səbr etsəniz, təqva göstərsəniz və onlar birdən üzərinizə gəlsələr, Rəbbiniz sizi beş min mələklə yardım edər ki, üzlərində izlər (müəyyən nişanələr) vardır.","ex":"Tərcümə: Ayə cavab olaraq möminlərin səbr və təqvası şərtilə Rəbbin beş min mələk göndərə biləcəyini qeyd edir və mələklərin üzərində müəyyən nişanələr olduğundan danışır. Şərh: “Müsawwimīn” (üzlərində nişanələr olan) ifadəsinin dəqiq mənası mətn daxilində mübahisəlidir; burada həm rəqəm, həm də şərt (səbr və təqva) vurğulanır.","rel":"8:9-10;3:124-126"},
 {"n":126,"ar":"وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ","tr":"Allah bunu yalnız sizin üçün müjdə və onunla qəlblərinizin əmin olması üçün etmişdir. Qələbə isə yalnız aləmlərin Qüdrətli, Həqiqət Sahibinin əlindəndir.","ex":"Tərcümə: Ayə bu yardımı möminlərə verilən sülh və əminlik xəbərçisi kimi təqdim edir və qələbənin yalnız Allahdan olduğunu bildirir. Şərh: Mətn burada müdaxilənin məqsətini—müjdə və qəlb rahatlığı—qeyd edir; bu, hadisənin mənəvi və ruhani əhəmiyyətinə diqqət çəkir.","rel":"3:123-125;8:10"},
 {"n":127,"ar":"لِيَقْطَعَ طَرَفًۭا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ","tr":"(Bütün bunlar) kafirlərin bir qismini məhv etmək və ya onları məhv edib geri dönmələrini təmin etmək üçündir ki, zərərli halda qayıtsınlar.","ex":"Tərcümə: Ayə bildirir ki, Allah kafirlərin müəyyən hissəsini məhv etmək və ya onları təhqir edib geri dönmüş vəziyyətdə qoymaq üçün hərəkət edə bilər. Şərh: Burada məqsəd düşmənin qüvvəsinin zəiflədilməsi və nəticədə məyusluqdur; kimin “kafir” hesab edildiyi və bu tədbirlərin konkret tətbiqi barədə mətn özü çərçivəsində qaldırılmalıdır.","rel":"3:123-126"},
 {"n":128,"ar":"لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ","tr":"Sənin bu məsələdə heç bir sözün yoxdur—ya onlara tövbə diləsin, ya da onları əzab etsin; çünki onlar zülmkardırlar.","ex":"Tərcümə: Ayə Peyğəmbərə istiqamətlənmiş şəkildə vəhyin sərb etdiyi hökmü göstərir ki, qərar Allaha məxsusdur və o ya Onlara rəhm edər, ya da cəza verər. Şərh: Mətn rəhbərin (Peyğəmbərin) qərarvermə səlahiyyətindən məhrum olduğunu və ilahi qərarın üstünlüyünü vurğulayır; “zülmkarlıq” burada onların əməllərinə işarə edir və qiymət mətn daxilində verilir.","rel":"3:127-129"},
 {"n":129,"ar":"وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ","tr":"Göylərdə və yerdə olanların hamısı Allaha məxsusdur. O, istədiyinə bağışlayar, istədiyinə əzab verər. Allah Bağışlayan, Rəhmli (Olandır).","ex":"Tərcümə: Ayə kainatın malikinin yalnız Allah olduğunu və bağışlama ilə əzab vermə haqqının Onun əlində olduğunu bildirir. Şərh: Mətn Allahın həm qüdrətini, həm də mərhəmətini birlikdə təqdim edir; “istədiyinə” ifadəsi ilahi hədəf seçimi ilə bağlı bəyanatdır və onun əhatə dairəsi mətn daxilində sadəcə olaraq göstərilir.","rel":"3:128;6:12"},
 {"n":130,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًۭا مُّضَٰعَفَةًۭ ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ","tr":"Ey iman gətirənlər! Riba (faiz)ı qat-qat artırılmış şəkildə yeməyin. Allahdan qorxun ki, bəlkə nicat tapasınız.","ex":"Tərcümə: Bu ayə möminlərə riba yeməkdən (yəni böyük şəkildə artırılmış qazanc əldə etməkdən) çəkindirməyi bildirir və təqva çağırışı edir. Şərh: Mətn riba ilə iqtisadi əxlaq və təqva arasında əlaqə qurur; “riba”nın konkret təfsiri və tətbiqi hüquqi və kontekstual müzakirə tələb edə bilər, burada isə əsas xəbərdarlıq və əxlaqi çağırış qeyd olunur.","rel":"2:275-279"},
 {"n":131,"ar":"وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ","tr":"O oddan qorxun ki, o kafirlər üçün hazırlandı.","ex":"Şərh: Ayə möminlərə gələcək cəza və təhlükədən xəbərdarlıq edir. Bu təfsir ayənin ümumi məğzinə aiddir; konkret kimlərin nəzərdə tutulduğu kontekstdə açıq qalır.","rel":""},
 {"n":132,"ar":"وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ","tr":"Allahın və Rəsulun əmrinə tabe olun ki, bəlkə rəhm olunasınız.","ex":"Şərh: Burada itaət imanla bağlı nəticə — rəhmət qazanmaq — ilə bağlanır. Tərcümə mətnin sadə mənasını verir; bu itaətin konkret formaları ayənin ümumi kontekstinə görə müəyyənləşdirilməlidir.","rel":""},
 {"n":133,"ar":"۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ","tr":"Rəbbinizdən bağışlanmağa və göylərin və yerin genişliyi qədər sahəsi olan cənnətə tələsin; o, muttaqilər üçün hazırlanmışdır.","ex":"Şərh: Ayə möminləri bağışlanma və böyük mükafata tərəf sürətlə addımlamağa çağırır. Burada “arzdəki genişlik” ifadəsi cənnətin böyüklüyünü vurğulayır; təfsir bu mənanı ifadə edir.","rel":""},
 {"n":134,"ar":"ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","tr":"Sərvət və dar gündə xərcləyənlər, qəzəbi saxlayan və insanları bağışlayanlar — Allah yaxşı iş görənləri sevir.","ex":"Şərh: Ayə mərhəmət, səbr və yardımsevərlik kimi əxlaqi keyfiyyətləri tərənnüm edir. Bu, davranışları təsvir edən şərhdir; konkret hallar üçün tətbiq fərqli ola bilər.","rel":""},
 {"n":135,"ar":"وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ","tr":"Və onlar ki, bir böyük günah və ya özlərinə zülm etdikdə Allahı xatırlayar, günahları üçün bağışlanma diləyərlər. Günahları kim bağışlayar, Allahdan başqasıı? Onlar etdikləri işdə bilərəkdən israr etməzlər.","ex":"Şərh: Ayə tövbənin, günahı dərk edib Allahdan bağışlanma istəməyin əhəmiyyətini göstərir. “Görərək israr etməmək” ifadəsi təkrar günaha düşməmək niyyətini vurğulayır; bu, təfsiri əks etdirir və mətnin özündən çıxarılan məna kimi verilir.","rel":""},
 {"n":136,"ar":"أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌۭ مِّن رَّبِّهِمْ وَجَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ","tr":"Onların mükafatı Rəbbindən bağışlanma və altında çaylar axan cənnətlərdir; orada əbədi qalacaqlar. Çalışanların mükafatı nə gözəldir!","ex":"Şərh: Ayə tövbə edən və yaxşı əməl sahibi olanların mükafatını təsvir edir. Bu izah müqəddəs mətnindirmənasınıdır; “əbədi qalmaq” ifadəsi kontekst əsasında anlaşılmalıdır.","rel":""},
 {"n":137,"ar":"قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌۭ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ","tr":"Sizdən əvvəl də təcrübələr (yollar) keçmişdir; yer üzündə gəzin və baxın ki, inkar edənlərin axırı necə olmuşdur.","ex":"Şərh: Ayə tarixdən ibrət götürməyi və keçmiş nümunələri müşahidə etməyi təşviq edir. Bu şərh ümumi ibrət anlayışını göstərir; konkret nümunələrin hansı olduğu ayədən kənar faktlara əsaslanmadan müəyyən edilmir.","rel":""},
 {"n":138,"ar":"هَٰذَا بَيَانٌۭ لِّلنَّاسِ وَهُدًۭى وَمَوْعِظَةٌۭ لِّلْمُتَّقِينَ","tr":"Bu insanlar üçün açıq izahdır, hidayət və muttaqilər üçün ibrətdir.","ex":"Şərh: Ayə mətnin özünü ümumi təsvir kimi təqdim edir — oxucular üçün izahat və nəsihət. Bu, ayənin funksiyasını göstərən interpretasiyadır, mətnin sözbəsöz mənasını tamamlayır.","rel":""},
 {"n":139,"ar":"وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ","tr":"Zəifləməyin və kədərlənməyin; əgər möminsinizsə, üstün olan sizsiniz.","ex":"Şərh: Ayə imanlıları əzmkarlığa və ümidə çağırır, çətin anlarda ruh düşkünlüyündən çəkindirməyi tövsiyə edir. Bu təfsir mötəbər məna verir; “üstün olmaq” ifadəsinin konkret tətbiqi kontekstdən asılıdır.","rel":""},
 {"n":140,"ar":"إِن يَمْسَسْكُمْ قَرْحٌۭ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌۭ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ","tr":"Əgər sizə bir bəlâ dəymişsə, elə bir zərbə də digər camaata dəymişdi. Bu günləri biz insanlar arasında növbə ilə döndəririk ki, Allah iman edənləri tanısın və sizdən şahidlər seçsin; Allah zalımları sevmir.","ex":"Şərh: Ayə çətinliklərin həm fərdi, həm də tarixi hal olduğunu və dövrlərin insanları imtahan etdiyini bildirir. “Şahidlər” (şuhədâ) kəlməsi həm “şahidlər”, həm də bəzi tərcümələrdə “şəhidlər” kimi oxuna bilər; burada mətnin özü bu mümkünlükləri açıq saxlayır.","rel":""},
 {"n":141,"ar":"وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ","tr":"Və Allah iman gətirənləri sınaqdan keçirsin və kafirləri məhv etsin.","ex":"İzah: Bu ayə bildirir ki, Allah möminləri təmizləmək və imtahan etmək məqsədilə sınaqlara məruz qoyar; kafirlərin məğlubiyyəti və yox olmağı da qeyd olunur. Təfsiri: «sınaqdan keçirmək» və «məhv etmək» ifadələrinin təfsiri müxtəlif ola bilər — burada imanların təmizlənməsi və ziddiyyətlərin ortaya çıxması nəzərdə tutulur, əminliklə biri kimi deyil, mümkün mənalar kimi verilir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":142,"ar":"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ","tr":"Sizcə cənnətə girəcəksinizmi, Allah hələ sizdən cihad edənləri və səbir edənləri bilməmişkən?","ex":"İzah: Ayə bildirir ki, cənnətə daxil olub-olmayacağın müəyyənləşməsi üçün Allahın kimlərin haqq yolda çalışdığını və kimlərin səbir etdiyini bilməsi lazımdır. Təfsiri: Burada vurğu Allahın bilik və imtahanına, həmçinin səbir və cihad kimi əməllərin sınaqda önəmli olmasına yönəlib; konkret tətbiqlər müxtəlif şəkildə başa düşülə bilər.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":143,"ar":"وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ","tr":"Siz əvvəllər ölümü qarşılamazdan əvvəl onu arzulayırdınız; sonra onu gördünüz və baxdınız.","ex":"İzah: Bu cümlə insanların əvvəlcə çətinliyə son qoymaq üçün ölümü arzuladıqlarını, sonra isə ölümün yaxınlığını görüb onu müşahidə etdiklərini bildirir. Təfsiri: «ölümü arzulamaq» və onun qarşılaşılması vəziyyəti müxtəlif kontekstlərdə — qorxu, cəsarət və ya qaçış arzusunun ifadəsi kimi — başa düşülə bilər; ayə konkret tarixi vəziyyəti xatırladır, amma ümumi anlam açıqlıq tələb edir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":144,"ar":"وَمَا مُحَمَّدٌ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًۭٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ","tr":"Məhəmməd isə yalnız bir elçidir; ondan əvvəl də elçilər gəlib keçmişdir. Əgər o ölsə və ya öldürülsə, siz geri dönərsinizmi? Kim arxaya dönsə, bu, Allaha heç nə ziyan verməz. Allah şükür edənləri mükafatlandıracaq.","ex":"İzah: Ayə peyğəmbərin insan olduğunu və onun ölümü halında islam ümmətinin işdən dönməməsi lazım olduğunu vurğulayır, həmçinin Allaha zərər gəlməyəcəyini bildirir. Təfsiri: Burada məna peyğəmbərin vəzifəsinin davam etməsi və inananların bağlılığının vacibliyi üzərindədir; «Allaha heç nə ziyan verə bilməz» ifadəsi Allahın müstəqilliyini və hakimiyyətinin dəyişməzliyini göstərir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":145,"ar":"وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًۭا مُّؤَجَّلًۭا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْءَاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّٰكِرِينَ","tr":"Heç bir can Allahın izni olmadan — yazılmış bir müddətə qədər — ölməz. Kim dünya mükafatı istəyirsə, ondan ona verərik; kim axirət mükafatı istəyirsə, ondan ona verərik. Biz şükür edənləri mükafatlandıracağıq.","ex":"İzah: Bu ayə ölümü Allahın izni və müəyyən edilmiş yazılı bir vaxtla əlaqələndirir, həmçinin dünyavî və axirətsiz mükafatların verilməsini qeyd edir. Təfsiri: «kitabı muəyyən edilmiş» ifadəsi nə qədər dəqiqlik tələb etsə də, əsas məqam Allahın ölümlə və mükafatla bağlı qərarının olmasıdır; hansı şəxsin hansı mükafatı alacağı kontekstə görə fərqli dərəcədə izah oluna bilər.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":146,"ar":"وَكَأَيِّن مِّن نَّبِىٍّۢ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌۭ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ","tr":"Çoxlu sayda ardıcılları ilə birlikdə döyüşən neçə peyğəmbər oldu; onlar Allah yolunda başlarına gələnlərə görə zəifləmədilər, əzilə düşmədilər və təslim olmadılar. Allah səbir edənləri sevir.","ex":"İzah: Ayə bir neçə peyğəmbərin və onların çoxlu izləyicilərinin döyüşlərdə və çətinliklərdə səbir və möhkəmlik göstərdiyini xatırladır. Təfsiri: Burada nümunə olaraq göstərilən qəhrəmanlıq və dözümlülük dəyərləri ümumi bir tərbiyə məqamı kimi təqdim edilir; konkret hadisələrin detalları ayədə əksik qalır, buna görə ümumi prinsiplər əsas götürülməlidir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":147,"ar":"وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ","tr":"Onların sözləri yalnız belə idi: “Rəb­bənā, günahlarımızı və işimizdə sərfiyyətimizi bağışla, ayaqlarımızı möhkəmləndir və bizi kafir qövmə qarşı yardım et.”","ex":"İzah: Bu dua möminlərin tövbə, səhvlərin bağışlanması, möhkəmlik və düşmənə qarşı kömək istəmək arzusunu göstərir. Təfsiri: Dua ifadələrinin sadəliyi və təvazökarlığı vurğulanır; «isrāf» sözünün mənası düzəliş tələb edir — həm maddi həddini aşmaq, həm də davranışlarındakı ifratlıq ola bilər — bu, dəqiq şərh tələb edir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":148,"ar":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ","tr":"Allah onlara dünyanın mükafatını və axirətin gözəl mükafatını verdi. Allah yaxşı işləyənləri sevir.","ex":"İzah: Ayə bildirir ki, onların duası və səyləri həm dünyada, həm də axirətdə mükafatlandırıldı və Allah yaxşı əməl sahiblərini sevir. Təfsiri: «dünyanın mükafatı» və «axirətin gözəl mükafatı» ifadələri müxtəlif növ nemət və müsbət nəticələrə işarə edə bilər; konkret niteliklər ayədə dəqiq göstərilmir.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":149,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ","tr":"Ey iman gətirənlər! Əgər kafirlərə tabe olsanız, onlar sizi arxaya — ziyana — qaytararlar.","ex":"İzah: Bu xəbərdarlıq iman gətirənləri kafirlərin məsləhətlərinə və tələblərinə boyun əyməməyə çağırır, çünki bu onları geri sürükləyər. Təfsiri: Burada «itaət» ictimai və siyasi təzyiqlərə müqavimət, həmçinin iman prinsiplərinə sadiqlik kimi başa düşülə bilər; konkret tətbiq kontekstdən asılıdır.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":150,"ar":"بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ","tr":"Xeyr! Allah sizin himayədarınızdır və O ən yaxşı yardımçıdır.","ex":"İzah: Bu ayə iman gətirənlərə Allahın onların himayədarı və ən güclü köməkçi olduğunu təsdiqləyir. Təfsiri: «mavlə»/«mavlā» sözü müxtəlif məna daşıya bilər (dost, himayədar, qoruyucu); burada əsas məqam Allahın qoruyuculuğu və dəstək verici mövqeyidir, hansı ki şübhəsiz olduğu vurğulanır.","rel":"Al‑ʻImrān (3:141‑150)"},
 {"n":151,"ar":"سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ","tr":"Biz kafir olanların ürəklərinə, Allahla şərik qoşduqları və Allahdan nazil edilməmiş bir hakimiyyətə görə qorxu salacağıq. Onların məskəni oddur; zülm edənlərin qalacağı yer nə pisdir.","ex":"Tərcümə: Ayə kafirlərin ürəklərinə qorxu salınacağını və onların əvəzinin odda olacağını bildirir. Şərh/şərait: “ما لمْ يُنَزِّلْ بِهِ سُلْطَانًا” ifadəsinin dəqiq təfsiri mətn daxilində bəlli deyil — burada həmin şərikin Allahdan olmayan bir səlahiyyət və ya iddia olduğu qeyd edilir və məna açıq-aydındır.","rel":"3:152,3:154"},
 {"n":152,"ar":"وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْءَاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ","tr":"Allah sizinlə öz vədini doğrultdu: Siz Onun izni ilə onlara toxunurdunuz, ta ki uğursuzluğa uğrayıb işi bölüşdürdünüz və Mən sizə sevdiyinizi göstərdikdən sonra da asi oldunuz. Sizindən bəziləri dünyanı, bəziləri axirəti istəyirdi; sonra O sizi onlardan ayırdı ki sizi sınağa çəksin; və O sizin üçün bağışlanma göstərdi. Allah möminlərə lütf sahibidir.","ex":"Tərcümə: Ayə Allahın verdiyi vədi xatırladığını və möminləri sınağa çəkdiyini bildirir. Şərh/şərait: Mətn fərqli istəklərə (dünya və axirət) malik olan qrupların mövcudluğunu və sınağın imanı ayırmaq məqsədini vurğulayır; bu, bir məna olaraq mətnə daxildir, amma konkret hadisə detallarını mətn özü müəyyən edir.","rel":"3:151-154"},
 {"n":153,"ar":"۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍۢ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّۢ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ","tr":"Siz qalxarkən heç kəsə geriyə baxmazdınız və Peyğəmbər sizi arxanızdan çağırırdı; Allah sizi hər kədərə qarşı kədər ilə mükafatlandırdı ki, həm itirən üçün, həm də olan üçün kədərlənməyəsiniz. Allah sizin nə etdiyinizi yaxşı xəbərdar edir.","ex":"Tərcümə: Ayə qısaca geri çəkilmə və Peyğəmbərin çağırışı zamanı əmələ gələn hisslərə işarə edir və Allahın bunlara cavab verdiyini qeyd edir. Şərh/şərait: “غَمًّا بِغَمٍّ” ifadəsi kədərin və ya sınayın əvəzinin necə verildiyi barədə bir təsvirdir; mətn bunu təsdiq edir, amma konkret emosiya və nəticələr barədə geniş şərh mətn xaricidir.","rel":"3:152,3:154"},
 {"n":154,"ar":"ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةًۭ نُّعَاسًۭا يَغْشَىٰ طَآئِفَةًۭ مِّنكُمْ ۖ وَطَآئِفَةٌۭ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍۢ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌۭ مَّا قُتِلْنَا هَٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","tr":"Sonra kədərdən sonra üzərinizə bir əminlik, yuxuya bənzər rahatlıq endirdi; sizdən bir qismi buna qapıldı, bir qismi isə öz daxilində narahat idi və cahiliyyə dövrü şübhəsi ilə Allah haqqında doğru olmayan şübhələr gətirdilər. Onlar soruşurdular: “Bizim işdə bir payımız varmı?” De: “Bütün iş Allahındır.” Onlar ürəklərində sənə demədiklərini gizlədirlər və deyirdilər: “Əgər bizə işdə bir pay olsaydı, burada öldürülməz və qətli olmazdıq.” De: “Əgər siz evlərinizdə olsaydınız, ölməyə yazılmış olanlar yataqlarından çıxıb gələrdilər.” Allah sizin sinənizdə olanı sınaqdan keçirmək və qəlblərinizi saflaşdırmaq üçün bunu etdi; O, sirlərin sahibidir.","ex":"Tərcümə: Ayə içi-səs və şübhə ilə bağlı müxtəlif qrupları, onların suallarını və Allaha aid olan qərarın məhz Allahın hökmündə olduğunu bildirir. Şərh/şərait: Mətn qəlblərin gizli niyyətlərini və sınağın məqsədini göstərir; “hansıların çıxıb gələcəyi” kimi ifadələr mətnin özündən alınan məntiqdir, əlavə spekulyasiyadan çəkinmək lazımdır.","rel":"3:152-155"},
 {"n":155,"ar":"إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌۭ","tr":"Həqiqətən sizdən geri dönənlər (ordu iki hissəyə bölündüyü gün) şeytanın onlara qazandırdığı bəzi etdikləri səbəbilə ayağını sürüşdürdülər; Allah onları bağışladı. Həqiqətən Allah bağışlayan və təmkin sahibidir.","ex":"Tərcümə: Ayə qaçan və ya geri dönənləri şeytanın aldadıcı təsiri və öz davranışlarının nəticəsi ilə izah edir və Allahın onların üstündən keçdiyini bildirir. Şərh/şərait: Burada “استزلّهم الشيطان” ifadəsi məsuliyyət və xarici təsirin birlikdə rol oynadığını göstərir; mətn öz-özlüyündə kimlərin və hansı hallarda bağışlandığını detallandırmır.","rel":"3:152,3:154"},
 {"n":156,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّۭى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةًۭ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ","tr":"Ey iman gətirənlər! Yerə çıxdıqda və ya səfərdə olarkən qardaşlarına “əgər onlar bizimlə olsaydılar, ölməz və qətlə yetirilə bilməzdilər” deyən kəslər kimi olmayın — Allah bunu onların qəlbində bir peşmanlıq üçün etdiyi üçün. Allah dirildir və öldürür; Allah etdiklərinizə baxandır.","ex":"Tərcümə: Ayə səfərdə və döyüşdə olmayanların qardaşları üçün qədərlənmə və paxıllıqdan çəkinmələrini tövsiyə edir və həyatın ölüm-qəza məsələlərinin Allaha aid olduğunu xatırladır. Şərh/şərait: Mətn başqalarının mövcudluğunu əsas gətirərək həyata nəticə çıxarmağı tənqid edir; ayə niyyət və mühakimənin düzgünlüyünü diqqətə çatdırır.","rel":"3:157-158"},
 {"n":157,"ar":"وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌۭ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌۭ مِّمَّا يَجْمَعُونَ","tr":"Əgər Allah yolunda öldürülsəniz və ya vəfat etsəniz, Allahdan bağışlanma və rəhmət vardır; bu, onların topladıqlarından daha xeyirlidir.","ex":"Tərcümə: Ayə şəhidlik və ya Allah yolunda ölümü Allahın bağışlaması və rəhməti ilə əlaqələndirir və bunun dünyəvi mənafələrdən daha üstün olduğunu bildirir. Şərh/şərait: Mətn bu vəziyyətə dəyər verir, amma konkret mükafatların təfsiri mətn daxilində sərt şəkildə müəyyənləşdirilməyib; əlavə ətraflı nəticələrdən çəkinmək lazımdır.","rel":"3:156-158"},
 {"n":158,"ar":"وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ","tr":"Əgər vəfat etsəniz və ya qətlə yetirilsəniz, şübhəsiz ki, Allahın huzuruna toplanacaqsınız.","ex":"Tərcümə: Ayə ölənlərin və qətlə yetirilənlərin Allah qarşısında toplanacağını açıqca bildirir. Şərh/şərait: Bu, dirilmə və hesab gününün mövcudluğunu göstərən qısa bəyanatdır; mətn bu toplanmanın necə olacağı barədə təfsilat vermir.","rel":"3:157-159"},
 {"n":159,"ar":"فَبِمَا رَحْمَةٍۢ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ","tr":"Allahın rəhməti sayəsində onlara yumşaq davrandın. Əgər sərt və qəlbi sərt olsaydın, onlar səndən ayrılardılar. Onları əfv et, onlar üçün bağışlanma dilə və işdə onlarla məsləhətləş; qərar verdikdə isə Allaha təvəkkül et. Həqiqətən Allah təvəkkül edənləri sevir.","ex":"Tərcümə: Ayə Peyğəmbərin mərhəmətli münasibətini və məsləhətləşmənin, əfv etmənin və Allaha təvəkkülün əhəmiyyətini vurğulayır. Şərh/şərait: Mətndə ünvan Peyğəmbərədir, amma bu davranış prinsipləri daha geniş tətbiq oluna bilər; “Allah sevər” ifadəsi təvəkkülün dəyərini bildirir.","rel":"3:160"},
 {"n":160,"ar":"إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ","tr":"Əgər Allah sizi yardım etsə, sizə heç kim üstün gəlməz; və əgər O sizi tərk etsə, Ondan sonra sizi kim yardım edə bilər? Ona görə də möminlər yalnız Allaha təvəkkül etsinlər.","ex":"Tərcümə: Ayə Allahın yardımının qələbə üçün qərarverici olduğunu və Allahın tərk etməsinin əvəzinin olmadığını bildirir. Şərh/şərait: Mətn inananlara təvəkkülün vacibliyini xatırladır; bu, Allahın yardımının əsas amil olduğunu göstərən qısa və özlü bəyanatdır.","rel":"3:159"},
 {"n":161,"ar":"وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ","tr":"Və heç bir peyğəmbərə yaraşmaz ki, (haqqı) zülm edərək ələ keçirsin; kim zülm edərsə, o gətirdiyini Qiyamət günündə gətirəcək. Sonra hər bir nəfs öz qazandığını tam olaraq alacaqdır və onlara zülm edilməyəcəkdir.","ex":"Tərcümə: Ayə peyğəmbərlərin haqsızlıq etməli olmadığını və hər kəsin etdiyi əməllərin hesabının veriləcəyini bildirir. Şərh: “yaghl” sözü burada haqsız rəftar etmək və ya başqasının haqqını ələ keçirmək mənasında işlənə bilər; ayə həm şəxsi məsuliyyəti, həm də axirətdə hesablaşmanı vurğulayır.","rel":"162-165"},
 {"n":162,"ar":"أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍۢ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ","tr":"Bəs Allahın razılığını tutanı ilə Allahın qəzəbini dəvət edən və məskəni Cəhənnəm olan kəs eyni ola bilərmi? Onlar üçün nə pis dönüşdür!","ex":"Tərcümə: Burada Allahın razılığı ilə Onun qəzəbinə düçar olma vəziyyəti müqayisə edilir. Şərh: Ayə iman və küfr arasındakı kəskin fərqi göstərir; “razı olmaq” və “qəzəb” anlayışları aydın şəkildə qarşılaşdırılır.","rel":"161,169-170"},
 {"n":163,"ar":"هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ","tr":"Onlar Allah yanında mərtəbələrə malikdirlər. Allah onların etdiklərini görür.","ex":"Tərcümə: Ayə möminlərin Allah yanında müxtəlif dərəcələrə malik olduğunu və Allahın onların əməllərini bildiyini deyir. Şərh: “dərəcələr” ifadəsi əməllərə və hal-ruhiyyəyə görə fərqli mükafat və mərtəbələrin ola biləcəyini bildirir; dəqiq ölçü və səbəblər ayədə konkretləşdirilməyib.","rel":"164"},
 {"n":164,"ar":"لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًۭا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍ","tr":"Həqiqətən Allah möminlərə lütf etmişdir: Onlardan özlərinə aid bir peyğəmbər göndərdi ki, ona ayələrini oxuyur, onları paklaşdırır və onlara Kitabı və hikməti öyrədir; halbuki onlar əvvəl açıq bir azğınlıq içində idilər.","ex":"Tərcümə: Ayə peyğəmbərin göndərilməsini möminlər üçün bir nemət kimi təqdim edir və onun təliminin paklaşdırma və öyrətmə funksiyalarını sadalayır. Şərh: “təzkiyə” (paklaşdırmaq) və “hədiyyə etmək” kimi ifadələr peyğəmbərin insanları mənəvi-təlim və kitab bilikləri ilə düzəltdiyi mənasında anlaşılır; bunların necə həyata keçirildiyi ayədə ümumi şəkildə bildirilib.","rel":"161-165"},
 {"n":165,"ar":"أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌۭ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ","tr":"Və sizə bir müsibət toxunduqda, siz də onun bənzərini etmişdiniz; siz dediniz: “Bu haradan gəldi?” De: “O, sizin özünüzdən bir şeydir.” Həqiqətən Allah hər şeyə qadirdir.","ex":"Tərcümə: Ayə insanları baş verən müsibətlərin bəzən onların öz əməllərinin nəticəsi olduğunu xatırlamağa çağırır və eyni zamanda Allahın qüdrətini qeyd edir. Şərh: Burada məsuliyyət və nəticə əlaqəsi vurğulanır; ayə konkret hadisəyə işarə edir, amma təfsiri məsələsində hansı əmələrin nəzərdə tutulduğunu ayə özü dəqiq şəkildə məhdudlaşdırmır.","rel":"166-167"},
 {"n":166,"ar":"وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ","tr":"Və (o olduqca) sizə o gün dəymiş şey, iki dəstənin qarşılaşdığı gün, Allahın izni ilə oldu ki, möminlər məlum olsun.","ex":"Tərcümə: Bu ayə iki qrupun toqquşduğu bir gündən bəhs edir və bunun Allahın izni ilə baş verdiyini bildirir. Şərh: Ayə hadisənin iman edənlərin niyyət və səviyyəsinin aşkara çıxmasına səbəb olduğunu göstərir; konkret tarixi və hadisənin təfsiri ayənin özündə verilmir.","rel":"167-168"},
 {"n":167,"ar":"وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًۭا لَّٱتَّبَعْنَٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ","tr":"Və hiyləkarlar da (məlum olsun) deyə: onlara söyləndi: “Gəlin, Allah yolunda vuruşun və ya dəf edin (müdafiə olun).” Onlar dedilər: “Əgər biz döyüşməyi bilsəydik, sizin ardınca gedərdik.” O gün onlar iman üzündən daha çox küfrə yaxın idilər. Diləri ilə ürəklərində olmayanı söyləyirdilər. Allah gizlətdiklərini yaxşı bilir.","ex":"Tərcümə: Ayə münafiqlərin davranışını təsvir edir — ağızları ilə dedikləri ilə qəlblərində olanın fərqli olduğunu bildirir. Şərh: Burada insanın zahiri ifadəsi ilə daxili vəziyyəti arasındakı fərq vurğulanır; “Allah onların gizlətdiklərini bilir” mətndə açıq şəkildə bildirilmişdir.","rel":"166-168"},
 {"n":168,"ar":"ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ","tr":"Onlar qardaşlarına deyib oturanlardır: “Əgər onlar bizim sözümüzə tabe olsaydılar, onlar öldürülməzdi.” De: “Əgər siz doğrudan da düz deyirsinizsə, ölümü özünüzdən uzaqlaşdırın.”","ex":"Tərcümə: Ayə, oturub çıxış verməyən və sonra keçmiş üçün bəhanə gətirənlərə yönələn bir cavabdır. Şərh: Bu ifadə tənqid və əks-sual şəklindədir — sözlərlə iddia etmək yetərli deyil; əgər iddia doğrudursa, nəticəni aradan qaldırmaq lazım idi; ayə həmçinin məsuliyyətli davranışın vacibliyini vurğulayır.","rel":"167-169"},
 {"n":169,"ar":"وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ","tr":"Allah yolunda öldürülənləri ölülər hesab etməyin; yox, onlar Rəbbinin yanında diridirlər və təmin olunurlar.","ex":"Tərcümə: Ayə şəhid sayılanların ölülər kimi hesab edilmədiyini və Allah yanında dirildiklərini bildirir. Şərh: “diridir” ifadəsi onların Rəbb tərəfində mənəvi və ya başqa cür bir həyat sürdüklərini və təmin olunduqlarını bildirir; bu “həyat”ın dəqiq mahiyyəti ayədə birbaşa izah olunmur və müxtəlif məqamlarda fərqli cəhətlərə işarə edə bilər.","rel":"170"},
 {"n":170,"ar":"فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","tr":"Onlar Allahın öz fəzli ilə onlara verdiklərinə şad olub sevinirlər və arxalarında qalan, hələ onlara qoşulmamış olanlar barədə sevinc içindədirlər ki, onların üstündə nə qorxu, nə də kədər olacaqdır.","ex":"Tərcümə: Ayə şəhidlərin Allahın verdiyi nemətlə sevinclə dolu olduqlarını və arxada qalanların da qorxu və kədərdən azad olacağını bildirir. Şərh: Burada həm möminlərin qarşılıqlı dua və ümidinə, həm də axirətdə təhlükəsizlik və sevincə işarə edilir; ayə arxada qalanların son vəziyyətinin qorunacağına dair müjdə verir.","rel":""},
 {"n":171,"ar":"۞ يَسْتَبْشِرُونَ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ","tr":"Onlar Allahın bir nemətinə və fəzilətinə sevinc içindədirlər; Allah möminlərin savabını heç vaxt boşa çıxarmır.","ex":"Bu ayə möminlərin Allahın neməti və fəziləti səbəbindən sevinclərini bildirir. Tərcümə ümumi məna verir; “Allah möminlərin əməllərinin mükafatını itirməz” ifadəsi interpretativ olaraq anlaşılır, mətnin əsas iddiasıdır.","rel":"3:172–174"},
 {"n":172,"ar":"ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ","tr":"Onlar Allahın və Rəsulun çağırışına cavab verdilər, yaralandıqdan sonra belə; onlardan yaxşı iş görənlərə və təqvalılara böyük bir mükafat vardır.","ex":"“الْقَرْحُ” sözü burada zədə və ya zərər mənasında işlənmişdir; nə qədər ki, mətndə dəqiq kontekst verilməyib, həm fiziki həm mənəvi zərər ola bilər. Ayə iman və itaətin, hətta əzaba məruz qalmış olarkən belə mükafatla nəticələnəcəyini vurğulayır.","rel":"3:171,3:173"},
 {"n":173,"ar":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًۭا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ","tr":"(Onlara) insanlar: “Görünür insanlar sizin üçün toplaşıblar, onlardan qorxun”– dedikdə, bu söz onların imanını artırdı və onlar dedilər: “Allahımız bizə kifayətdir və O nə gözəl vəkildir.”","ex":"Ayə göstərir ki, başqalarının qorxudaraq xəbər verməsi imanı zəiflətmədi, əksinə gücləndirdi və etimadın ifadəsi olaraq “حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ” deyildi. Bu ifadənin imanlıların etibar və təvəkkülünü əks etdirdiyi anlaşılır.","rel":"3:171–174"},
 {"n":174,"ar":"فَٱنقَلَبُوا۟ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ لَّمْ يَمْسَسْهُمْ سُوٓءٌۭ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ","tr":"Beləcə onlar Allahın neməti və fəziləti ilə qayıtdılar; onlara heç bir pislik dəymədi və Allahın razılığını seçdilər. Allah isə böyük fəzilət sahibidir.","ex":"Bu ayə öncəki bəyanın nəticəsini bildirir: iman edənlərin nemətə qayıtmaları və zərər görməmələri, Allahın razılığını izləməklə əlaqələndirilir. Təfsiri olaraq vurğulanır ki, “nemət” həm maddi həm mənəvi yardımı ifadə edə bilər; mətndə konkretləşdirilməyib.","rel":"3:171–173"},
 {"n":175,"ar":"إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ","tr":"Bu yalnız şeytandır ki, dostlarını qorxuda-sındırır; onlardan qorxmayın. Əgər möminsinizsə, Allahdan qorxun.","ex":"Ayə şeytanın dostlarını qorxu ilə necə idarə etdiyini göstərir və möminlərə insanlardan yox, Allaha qorxu və təvəkkül göstərməyi əmr edir. Mətnin sintaktikası qısa və əmr tərzindədir; mənası dəqiq olsa da, bəzi qiraət fərqlilikləri mövcuddur və burada əsas mesaj qorxunun mənbəyidir.","rel":"3:173–174"},
 {"n":176,"ar":"وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّۭا فِى ٱلْءَاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ","tr":"Səni tezliklə küfrə dalanlar kədərləndirməsinlər; onlar Allah üçün heç bir zərər yetirə bilməzlər. Allah onların axirətdə pay sahibi olmamalarını istəyir və onlar üçün böyük bir əzab var.","ex":"Bu ayə möminlərə belə şəxslərdən kədərlənməmək barədə təsəlli verir və onların Allahın planına zərər verə bilməyəcəyini bildirir. Ayənin soncəsi gələcəkdə onların cəza ilə üzləşəcəklərini ifadə edir; burada ilahi ədalət prinsipinə işarə edilir.","rel":"3:177–179"},
 {"n":177,"ar":"إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا وَلَهُمْ عَذَابٌ أَلِيمٌۭ","tr":"Küfrü imana dəyişənlər (imandan çıxıb küfrə qayıdanlar) Allah üçün heç bir zərər verə bilməzlər; onlar üçün acı bir əzab var.","ex":"“اشتَرُوا الكفر بالإيمان” ifadəsi imanla küfr arasında alış-veriş edənləri təsvir edir — yəni imandan əl çəkməyi seçənlər. Ayə vurğulayır ki, bu cür insanların hərəkətləri Allaha zərər verməyəcək, lakin özləri üçün ağır nəticələr doğuracaq.","rel":"3:176,3:178"},
 {"n":178,"ar":"وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌۭ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًۭا ۚ وَلَهُمْ عَذَابٌۭ مُّهِينٌۭ","tr":"Kafir olanlar elə düşünməsinlər ki, biz onlara müddət veririk ki, bu özləri üçün xeyirdir; əksinə, onlara müddət veririk ki, günahları artsın; onlar üçün alçaldıcı bir əzab vardır.","ex":"Burada “نُمَلِّي لَهُمْ” – sağlamaq, müddət vermək mənasında işlənib və bu təxirə salınmanın onların xeyrinə olmadığı bildirilir. Mətnə görə Allahın təxirə salması onların günahlarının artmasına səbəb olur və bu, gələcəkdə cəza ilə nəticələnəcəkdir.","rel":"3:176–177"},
 {"n":179,"ar":"مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌۭ","tr":"Allah möminləri elə vəziyyətdə buraxmaz ki, siz olduğunuz kimi qalsınlar; ta ki, pis ilə yaxşı arasını fərq edə bilsin. Allah sizə gələcək barədə (tam) xəbəri verməz; lakin Allah öz peyğəmbərlərindən istədiklərini seçər. Ona görə Allaha və Onun peyğəmbərlərinə iman gətirin; əgər iman gətirsəniz və təqvalı olsanız sizə böyük bir mükafat vardır.","ex":"Ayə iki əsas məqamı birləşdirir: sınaq yolu ilə xeyir və şəri ayırma və Allahın qiyamət/ğayb barədə açıqlama verməməsi; peyğəmbərlərin seçiminin Allaha aid olduğu vurğulanır. “يَمِيزَ” sözünün mənası sınaq və fərqləndirmə kimi anlaşılır; bəzi təfsirlərdə bu prosesin necə baş verməsi barədə müxtəlif yozumlar mövcuddur, amma mətndə əsas fikir açıqdı­r.","rel":"3:180–181"},
 {"n":180,"ar":"وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًۭا لَّهُم ۖ بَلْ هُوَ شَرٌّۭ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ","tr":"Allahın ona verdiyi fəzildən xəsislik edənlər zənn etməsinlər ki, bu onlar üçün xeyirdir; əksinə, bu onlar üçün şərdir. Qiyamət günündə onlar xəsislik etdikləri şeylərlə boyunlarına bürünəcəklər. Göylərin və yerin mirası Allaha məxsusdur; Allah etdiklərinizdən xəbərdardır.","ex":"Ayə xəsislik və malı xərcləməməyin mənfi nəticələrini bildirir; “يُطَوَّقُونَ” ifadəsi metaforik şəkildə vergi və ya cəza kimi onların boyunlarına qoyulma mənasında istifadə olunur. Nəhayət, mülkiyyətin gerçək sahibi kimi Allahın hamıdan xəbərdar olduğu xatırladılır.","rel":"3:172–179"},
 {"n":181,"ar":"لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌۭ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ","tr":"Həqiqətən Allah onların “Allah kasıbdır, biz isə varlıyıq” sözünü eşitdi. Biz onların dediklərini və peyğəmbərləri haqqsız öldürmələrini yazacağıq və (onlara) deyəcəyik: “Alov əzabını dadın.”","ex":"İlk layihə: Bu tərcümə ayədə görünəni birbaşa ifadə edir. Şərh (təfsir): Ayə onların (bəzi insan qruplarının) Allahın kasıb olduğu və özlərinin varlı olduqları iddiasını və peyğəmbərləri haqqsız öldürmələrini qeyd edir; mətn Allahın bunu yazıb cəza olaraq alov əzabını bəyan edəcəyini bildirir. Bu izah tərcümənin şərhidir, mübahisəli məqamlar olduğu halda qeyri-müəyyənlik saxlanılır.","rel":""},
 {"n":182,"ar":"ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍۢ لِّلْعَبِيدِ","tr":"Bu, sizin əllərinizin qabaqcadan etdiklərinizə görədir; Allah qullara zülm edən deyildir.","ex":"İlk layihə: Tərcümə ayənin açıq mənasını verir. Şərh: Burada cəza və məsuliyyət insanların öz əməllərinə bağlanır və Allahın ədalətsiz olmadığı vurğulanır; bu, əməl-nəticə qanununa işarədir. Bu izah mətnin özündən çıxarılan mənadır, şərhi nisbətən ehtiyatlı saxlanılır.","rel":""},
 {"n":183,"ar":"ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍۢ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌۭ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ","tr":"(O kəslər) dedilər: “Allah bizə and içib ki, peyğəmbərə inanmayacağıq, ta ki o bizə odun içində yanacaq bir qurban gətirsin.” De: “Sizə mənim əvvəlimdə də açıq dəlillərlə və sizin dediyinizə bənzər şeylərlə peyğəmbərlər gəlib; əgər doğrusunuzsa niyə onları öldürdünüz?”","ex":"İlk layihə: Tərcümə sözlərin ilkin mənasını əks etdirir. Şərh: Ayə bəzi qrupların peyğəmbərlərə qoyduqları şərtləri və əvvəlki peyğəmbərlərin oxşar müqavimətlə qarşılaşdığını xatırladır; təfsir olaraq burada onların niyyət və hərəkətləri sorğulanır. Qərar və nəticələr barədə qeyri-müəyyən tərəflər ehtiyatla ifadə olunur.","rel":""},
 {"n":184,"ar":"فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌۭ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ","tr":"Əgər səni (inkar etsələr), bilin ki, sənə qədər də peyğəmbərlər inkaredilmişdi; onlar açıq dəlillərlə, (mövcud) kitabla və nurlu kitabla gəldilər.","ex":"İlk layihə: Tərcümə ayənin bildirməsini sadə şəkildə çatdırır. Şərh: Bu cümlə peyğəmbərlərin aydın dəlillərlə göndərildiyini və buna baxmayaraq dəfələrlə rədd edildiklərini vurğulayır; “zəbur” və “nurlu kitab” ifadələrinin konkret tərifi mətn daxilində dəqiqləşdirilməlidir. Müxtəlif oxunuşların ola biləcəyini qeyd etmək lazımdır.","rel":""},
 {"n":185,"ar":"كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ","tr":"Hər bir can ölümü dadacaq. Əsl mükafatlarınız yalnız Qiyamət günündə tam veriləcəkdir; kim oddan çəkilsə və cənnətə daxil olarsa, həqiqətən qurtuluş tapmışdır. Dünyanın həyatı isə aldanışdan başqa bir şey deyildir.","ex":"İlk layihə: Tərcümə ayənin əsas mövzusunu — ölüm, mükafat və dünyanın aldanış xarakterini — çatdırır. Şərh: “Hər can ölümü dadacaq” ifadəsi ümumi sonluq haqda xəbərdarlıqdır və dünyəvi xarakterin müvəqqəti olduğunu vurğulayır; bu, əxlaqi nəticələr üçün əsas kimi göstərilir. Təfsiri mətnin özündə olan fikrə əsaslanır və əlavə iddialardan çəkinir.","rel":"29:57"},
 {"n":186,"ar":"۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًۭى كَثِيرًۭا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ","tr":"Şübhəsiz, siz sərvətlərinizdə və özlərinizdə sınağa məruz qalacaqsınız və sizdən öncə Kitab verilənlərdən və müşriklərdən çox zülm və əziyyət eşidəcəksiniz. Əgər səbirli olsanız və təqva göstərsəniz, bu, ciddi işlərdə qərarlılıqdır.","ex":"İlk layihə: Tərcümə sınaq, sözlü təzyiq və səbir-təqvaya çağırışı bildirir. Şərh: Ayə iman edənlərin qarşılaşacağı sınaqların maddi və şəxsi sahələrdə olacağını və səbir ilə təqvanın bu vəziyyətlərdə əhəmiyyətini vurğulayır; “azm” (qərarlılıq) anlayışı burada pozitiv keyfiyyət kimi təqdim edilir. İzah mətn əsasına söykənir və əlavə qanuniləşdirmədən qaçır.","rel":""},
 {"n":187,"ar":"وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَبِئْسَ مَا يَشْتَرُونَ","tr":"(Unutmayın ki) Allah Kitab verilənlərdən əhd alanda: “Onu insanlara açıqlayacaqsınız, gizlətməyəcəksiniz” demişdi; onlar isə onu arxalarına atdılar və onu az qiymətə dəyişdilər. Pisdir onlar nə üçün aldılar.","ex":"İlk layihə: Tərcümə ayənin hüquqi-mənəvi məsuliyyəti və onu pozanların davranışını göstərir. Şərh: Burada Kitab sahibi sayılanların vəzifəsi — kitabı başqalarına çatdırmaqdır; ayə onların bunu gizlətmələrini və materialist maraqlarla əvəz etmələrini tənqid edir. Bu şərh mətnin öz iddiasına əsaslanır və tarixiləşdirici detallar təqdim etmir.","rel":""},
 {"n":188,"ar":"لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍۢ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ","tr":"Heç vaxt düşünməyin ki, əllərinə verilənlərlə sevinən və başqalarının etmədikləri işlərlə tərifə layiq görülməyi sevənlər təhlükəsizdir; onlara şiddətli bir əzab vardır.","ex":"İlk layihə: Tərcümə nüfuz və şöhrət üçün uydurulmuş göstəricilərin təhlükəsini xəbərdar edir. Şərh: Ayə göstərir ki, özlərini başqalarının işləri hesabına göstərən və saxta təqdirə meylli olanlar üçün cəza mövcuddur; bu, şəxsi dürüstlük məsələsini önə çıxarır. Təfsir mətnə əsaslanır və əlavə sübut tələb etmir.","rel":""},
 {"n":189,"ar":"وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ","tr":"Göylərin və yerin mülkü Allahındır; Allah hər şeyə qadirdir.","ex":"İlk layihə: Tərcümə Allahın hakimiyyət və qüdrətini qısa şəkildə ifadə edir. Şərh: Bu ayə Allahın kainat üzərində hökmranlığını və hər işi görmək qüdrətini vurğulayır; bu, mətnin ümumi mövzusuna — məsuliyyət və hesab gününə — yoxlanış kimi təsir edir. İzah sadə və mətnə söykənir.","rel":""},
 {"n":190,"ar":"إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلْأَلْبَٰبِ","tr":"Həqiqətən, göylərin və yerin yaradılışında və gecə ilə gündüzün dəyişməsində düşünənlər üçün ayətlər vardır.","ex":"İlk layihə: Tərcümə yaradılışda və zamanın dəyişməsində dəlillərin olduğunu bildirir. Şərh: “Ayətlər” anlayışı burada yaradılışın mülahizəyə və inanmağa dəvət edən əlamət olduğunu göstərir; bu, möminlər üçün düşüncə və iman üçün zəmin yaradır. Təfsir mətnin öz tropundan çıxarılmayaraq verilib.","rel":""},
 {"n":191,"ar":"ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًۭا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","tr":"Onlar Allahı ayaqda, oturanda və yanları üstündə xatırlayan və göylərin və yerin yaradılışı üzərində düşündükləridir. (Onlar dua edirlər:) “Ey Rəbbimiz! Sən bunu boşuna yaratmamısan. Paklıq sənə yaraşır, bizi Odun əzabından qoru.”","ex":"Şərh: Ayə Allahı müxtəlif vəziyyətlərdə xatırlayanların və kainətin yaradılışı üzündə düşünənlərin sədaqətini təsvir edir. Təfsiri: Dua sözləri onların yaradılışın məqsədi barədə yaranan qəti inamını və Axirət qurtuluşu üçün edilən yalvarışı göstərir; bu oxunuş müxtəlif insan hallarına münasibətdə ibadətin davamlılığını vurğulayır.","rel":"2:164, 51:20-21"},
 {"n":192,"ar":"رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ","tr":"Ey Rəbbimiz! Həqiqətən Sən kimsəni Odun içinə daxil etsən, onu utandırmış olarsan. Zülm edənlərin heç bir müdafiəçisi yoxdur.","ex":"Şərh: Bu cümlə Cəhənnəmə daxil olmağın insan üçün alçaldıcı nəticəsini ifadə edir. Təfsiri: Burada Allahın hökmü və onun nəticələrinin gerçəkliyi vurğulanır; “müdafiəçi yoxdur” ifadəsi axirətdə kimsənin zalimləri xilas edə bilməyəcəyinə işarə edir.","rel":"39:71"},
 {"n":193,"ar":"رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ","tr":"Ey Rəbbimiz! Həqiqətən biz bir çağırıcının imana çağırdığını eşitdik: “Rəbbinizə iman gətirin.” Biz də iman gətirdik. Ey Rəbbimiz! Günahlarımızı bağışla, pis əməllərimizi sil və bizi salehlərlə birlikdə qəbul et.","ex":"Şərh: Burada möminlərin iman gətirmələrinə səbəb olan çağırışa rəddolunmaz cavab və bağışlanma istəyi göstərilir. Təfsiri: Dua həm şəxsi tövbə, həm də icma ilə birlikdə salehlərlə qovuşmaq istəyi kimi oxuna bilər; bəzi mətnlərdə “münadi”nin mənası və kim olduğu açıq göstərilməyib, ona görə tam detallı identifikasiya mətn xaricində qalmışdır.","rel":"2:25, 4:74"},
 {"n":194,"ar":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ","tr":"Ey Rəbbimiz! Rəsulların vasitəsilə bizə vəd etdiyin şeyi bizə ver və Qiyamət günü bizi utandırma. Həqiqətən, sən vədi pozmazsan.","ex":"Şərh: Bu dua Allahın peyğəmbərlər vasitəsilə verilən vədini xatırlayır və günahkar halda utanc gətirilməməsi üçün olan istəyi ifadə edir. Təfsiri: “Sən vədi pozmazsan” cümləsi Allahın vədinin sadiqliyinə etimadı göstərir; necə ki, duası konkret olaraq rəsullardan gələn vədlərlə bağlıdır, onların nə qədər geniş və ya məhdud olduğu ayə özündə dəqiq müəyyənləşmir.","rel":"10:94"},
 {"n":195,"ar":"فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍۢ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍۢ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ","tr":"Rəbbələri onlara belə cavab verdi: “Mən sizin hər hansı birinizin əməyini — kişi olsun, qadın olsun — boşa çıxarmaram; siz bir-birinizə məxsussunuz. Məhz hicrət etmiş, evlərindən çıxarılmış, mənim yolumda əzab görmüş, döyüşmüş və öldürülmüş olanları günahlarından təmizləyər və onları Allahın yanından gələn mükafat olaraq altından çaylar axan cənnətlərə daxil edərəm. Allah tərəfdə ən yaxşı mükafat vardır.”","ex":"Şərh: Allahın cavabı əməyin cinsdən asılı olmayaraq dəyərləndiriləcəyini və yolda çəkilən əzabların əvəzsiz mükafatla mükafatlandırılacağını bəyan edir. Təfsiri: Burada hicrət, sürgün, əzab, döyüş və şəhadətin Allah yanında xüsusi qiymət qazandığı vurğulanır; “əməyin boşa çıxmayacağı” anlayışı həm bu dünyadakı, həm də axirətdəki nəticələri əhatə edə bilər.","rel":"2:218, 4:100"},
 {"n":196,"ar":"لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ","tr":"Kafir olanların ölkələrdə dolanması səni aldatmasın.","ex":"Şərh: Qısa xəbərdir: kâfirlərin dünyəvi hərəkətləri və qüvvət göstərmələri aldanmamalıdır. Təfsiri: Bu ifadə onların müvəqqəti güc və sərbəst hərəkətlərinin son nəticəsini (axirətdəki cəzalarını və ya fani üstünlüklərin boşluğunu) örtməməli olduğunu xəbər verir; dəqiq kontekst mətn daxilində bu hərəkətlərin mahiyyətini müəyyən edir.","rel":"29:64"},
 {"n":197,"ar":"مَتَٰعٌۭ قَلِيلٌۭ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ","tr":"Bu onlara qısa bir zövqdür; sonra onların mənzili Cəhənnəmdir — nə pis məskəndir.","ex":"Şərh: Ayə dünyəvi zövqlərin fani olduğunu və əsl nəticənin Cəhənnəm olacağını təsvir edir. Təfsiri: “Qısa zövq” ifadəsi dünyanın keçiciliyini vurğulayır; burada hansı qrupların nəzərdə tutulduğu yaxın ayələrdən oxunmalıdır, çünki ümumi və konkret hallar arasında fərq var.","rel":"29:64"},
 {"n":198,"ar":"لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ لِّلْأَبْرَارِ","tr":"Ancaq Rəbbindən qorxanların üçün altından çaylar axan cənnətlər vardır; onlar orada əbədi qalacaqlar — bu Allahdan bir məskəndir. Allah yanında olan (mükafat) salehlər üçün daha xeyirlidir.","ex":"Şərh: Ayə saleh olanların əbədi mükafatını — cənnəti və onun altından axan çayları — və Allah yanında daha yaxşı bir mükafatın olduğunu bildirir. Təfsiri: “Allah yanında olan” ifadəsi axirətdəki daimi mükafatın dünyanın hər növ mükafatından üstündür olduğunu vurğulayır; cənnət təsvirləri simvolik və ya həqiqi ola bilər, mətn bunu konkret şəkildə məhdudlaşdırmır.","rel":"2:25, 18:31"},
 {"n":199,"ar":"وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۗ أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ","tr":"Və həqiqətən Kitab əhlindən də bəziləri var ki, Allaha və sizə nazil edilənə və onlara nazil edilənə iman gətirirlər; Allah qarşısında xuşu içindədirlər. Onlar Allahın ayələrini kiçik bir qiymətə satmırlar. Onların mükafatı Rəbbinin yanındadır. Həqiqətən Allah hesab baxımından sürətlidir.","ex":"Şərh: Ayə Kitab əhlinin bir hissəsinin imanını və onların dürüst davranışını vurğulayır, eyni zamanda Allahın sürətli hesab vermə qüdrətinə işarə edir. Təfsiri: “Ayələri kiçik bir qiymətə satmamaq” ifadəsi iman və sadiqlik müqabilində dünya mənafelərinə güzəşt etməmək deməkdir; belə insanların mükafatı tamamilə Rəbbin əlindədir.","rel":"2:62"},
 {"n":200,"ar":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ","tr":"Ey iman gətirənlər! Səbir edin, bir-birinizə də səbir göstərin, mövqelərinizi qoruyun və Allahdan qorxun ki, nicat tapasınız.","ex":"Şərh: Bu əmr möminlərə səbirli və davamlı olmalarını, həm şəxsi həm də icma olaraq möhkəm dayanmalarını tövsiyə edir. Təfsiri: “Mövqelərinizi qoruyun” ifadəsi həm mənəvi mövqe, həm də lazım gələndə təhlükəsizlik baxımından hazırlıq mənasında oxuna bilər; ayənin praktik tətbiqi şəraitdən asılı olaraq dəyişə bilər.","rel":"2:153"}
]};
